 b.onpointerenter=e=>{if(e.pointerType==='touch'||menuPinned)return;if(Math.abs(e.clientX-downPt.x)<6&&Math.abs(e.clientY-downPt.y)<6)return;if(performance.now()-lastClose.t<700&&e.clientX===lastClose.x&&e.clientY===lastClose.y)return;clearTimeout(leaveTimer);clearTimeout(enterTimer);enterTimer=setTimeout(()=>{if(trigger!==b||pop.dataset.open!=='true')open();},80);};
