function estimate(m){const up=outcomes(m).find(o=>/^up$/i.test(o.name));if(!up)return '';const v=Number(m.lowerBound)/1e18+up.p/100*(Number(m.upperBound)-Number(m.lowerBound))/1e18;const unit=m.marketName.match(/\[([^\]]+)\]\s*$/)?.[1]||'';return `${num(v)}${unit&&!/^note$/i.test(unit)?' '+esc(unit):''}`;}
