function ring(m,size=56){const o=outcomes(m),sum=o.reduce((s,x)=>s+x.p,0),den=Math.max(100,sum),sw=8,r=(size-sw)/2,C=2*Math.PI*r;let off=0;
 const seg=o.slice(0,2).map((x,j)=>{const len=C*clamp(x.p)/den,s=`<circle r="${r}" cx="${size/2}" cy="${size/2}" fill="none" stroke="${paint(x,j)}" stroke-width="${sw}" stroke-dasharray="${Math.max(0,len-1).toFixed(2)} ${C.toFixed(2)}" stroke-dashoffset="${(-off).toFixed(2)}"/>`;off+=len;return s;}).join('');
 return `<svg class="ring" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" role="img" aria-label="${esc(o.slice(0,2).map(x=>x.name+' '+pct(x.p)+'%').join(', '))}"><g transform="rotate(-90 ${size/2} ${size/2})"><circle r="${r}" cx="${size/2}" cy="${size/2}" fill="none" stroke="${color(null,2)}" stroke-opacity=".45" stroke-width="${sw}"/>${seg}</g></svg>`;}
function legend(m,cls=''){return `<ul class="lg ${cls}">${top2(m).map((x,j)=>`<li class="o${j+1}"><i aria-hidden="true"></i><span title="${esc(x.name)}">${esc(x.name)}</span><b class="num">${pct(x.p)}%</b></li>`).join('')}</ul>`;}
const hc={i:0,timer:null,paused:false};
function slide(m,i,n){const on=i===hc.i;return `<article class="hc-slide${on?' on':''}" data-i="${i}" role="group" aria-roledescription="slide" aria-label="${i+1} of ${n}"${on?'':' aria-hidden="true" inert'}><div class="hc-media">${mkImg(m,'hc-img',i<2)}</div><div class="hc-body"><div class="hc-chips"><span class="hc-chip">${kind(m)}</span><span class="hc-chip">${shortStatus(m)}</span><span class="hc-rank num">#${i+1} most traded</span></div><h2 class="hc-q" title="${esc(m.marketName)}">${esc(m.marketName)}</h2><div class="hc-row">${legend(m,'hc-lg')}<span class="hc-vol num">${money(m.volumeUSD)}<small>traded</small></span><button class="primary hc-view" data-pick="${m.id}">View market</button></div></div></article>`;}
function hero(){const top=topFive(),n=top.length;if(hc.i>=n)hc.i=0;
 const fan=[18,62,110,158,202].map((y,k)=>`<path d="M0 110C96 110 120 ${y} 260 ${y}" style="--k:${k}"/>`).join('');
 return `<section class="hero hc" id="hc" aria-roledescription="carousel" aria-label="Most traded markets"><div class="hc-slides">${top.map((m,i)=>slide(m,i,n)).join('')}</div><svg class="hc-fan" viewBox="0 0 260 220" preserveAspectRatio="none" aria-hidden="true">${fan}</svg><div class="hc-ctrl"><button class="hc-arrow" data-hc="-1" aria-label="Previous market">${hIcon('back')}</button><div class="hc-dots" role="group" aria-label="Choose market">${top.map((m,i)=>`<button class="hc-dot" data-hc-go="${i}" aria-label="Market ${i+1} of ${n}" aria-current="${i===hc.i}"><i></i></button>`).join('')}</div><button class="hc-arrow" data-hc="1" aria-label="Next market">${hIcon('next')}</button></div></section>`;}
function wireHero(){const root=$('#hc');if(!root)return;const slides=$$('.hc-slide',root),dots=$$('.hc-dot',root),n=slides.length;if(!n)return;
 const schedule=()=>{clearTimeout(hc.timer);dots.forEach(d=>d.classList.remove('run'));if(reduced()||hc.paused||!root.isConnected)return;const d=dots[hc.i];void d.offsetWidth;d.classList.add('run');hc.timer=setTimeout(()=>{if(root.isConnected)go(hc.i+1);},6000);};
 const go=k=>{hc.i=(k+n)%n;slides.forEach((s,j)=>{const on=j===hc.i;s.classList.toggle('on',on);s.inert=!on;if(on)s.removeAttribute('aria-hidden');else s.setAttribute('aria-hidden','true');});dots.forEach((d,j)=>d.setAttribute('aria-current',String(j===hc.i)));schedule();};
 root.querySelectorAll('[data-hc]').forEach(b=>b.onclick=()=>go(hc.i+Number(b.dataset.hc)));
 dots.forEach((d,j)=>d.onclick=()=>go(j));
 root.querySelectorAll('.hc-view').forEach(b=>b.onclick=e=>{e.stopPropagation();location.hash='#/market/'+b.dataset.pick;});
 root.querySelectorAll('.hc-slide').forEach(sl=>{sl.style.cursor='pointer';sl.addEventListener('click',e=>{if(e.target.closest('button,a'))return;const id=sl.querySelector('.hc-view')?.dataset.pick;if(id)location.hash='#/market/'+id;});});
 root.onpointerenter=e=>{if(e.pointerType!=='mouse')return;hc.paused=true;schedule();};
 root.onpointerleave=e=>{if(e.pointerType!=='mouse')return;hc.paused=root.contains(document.activeElement);schedule();};
 root.addEventListener('focusin',()=>{hc.paused=true;schedule();});
 root.addEventListener('focusout',e=>{if(!root.contains(e.relatedTarget)){hc.paused=root.matches(':hover');schedule();}});
 root.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();go(hc.i+(e.key==='ArrowRight'?1:-1));}});
 let sx=null;root.addEventListener('pointerdown',e=>{sx=e.pointerType==='mouse'?null:e.clientX;});root.addEventListener('pointercancel',()=>{sx=null;});
 root.addEventListener('pointerup',e=>{if(sx==null)return;const dx=e.clientX-sx;sx=null;if(Math.abs(dx)>40)go(hc.i+(dx<0?1:-1));});
 go(hc.i);}
let fanRO;function drawFan(){}function markFan(){}

/* Toolbar */
const viewSeg=()=>`<div class="seg view-seg" role="group" aria-label="View">${[['tiles','Tiles'],['table','Index'],['activity','Activity']].map(([v,l])=>`<button data-view="${v}" aria-pressed="${state.view===v}">${hIcon({tiles:'grid',table:'table',activity:'activity'}[v])}<span>${l}</span></button>`).join('')}</div>`;
function stripIcon(kind){const map={Topic:'grid',State:'activity',Verified:'verified',Chain:'chain',Type:'layers',Advanced:'sliders',Sort:'sort',Clear:'close',Open:'arrow',Copy:'copy',Help:'help',Star:'star'};return hIcon(map[kind]||'help');}
function advancedCount(){return [state.rewards,Number(state.minLiquidity)>0].filter(Boolean).length;}
function stripTrigger(k){const name=k==='Advanced'?'More':k,value=k==='Sort'?(SORT_LABELS.find(s=>s[0]===state.sort)||[,'Volume'])[1]:state.filters[k],active=k==='Advanced'?advancedCount():k!=='Sort'&&value&&value!=='All'?1:0;return `<button class="strip-control ${active?'is-active':''}" data-filter="${k}" aria-expanded="false" aria-label="${name}${value&&value!=='All'?': '+esc(value):''}" title="${name}">${stripIcon(k)}<span class="strip-label">${k==='Sort'?'Sort':name}</span>${value&&value!=='All'?`<span class="strip-value">${esc(value)}</span>`:''}</button>`;}
function toolsRow(count){const active=Object.values(state.filters).some(v=>v&&v!=='All')||advancedCount()||state.query||state.asker;
 const asker=state.asker?`<span class="asker-chip"><span class="ac-cap">Asker profile</span><a class="mono" href="${explorer(state.listMarkets.find(m=>m.creator===state.asker)||{})}/address/${state.asker}" target="_blank" rel="noopener noreferrer" title="${state.asker}">${short(state.asker)}</a><span class="num">${askerCount(state.asker)} markets</span><button data-clear-asker aria-label="Clear asker filter">${stripIcon('Clear')}</button></span>`:'';
 return `<div class="ix-tools" role="group" aria-label="Filters"><div class="ix-filters">${['Topic','State','Verified','Chain','Type','Advanced'].map(stripTrigger).join('')}${state.view==='tiles'?stripTrigger('Sort'):''}</div><div class="ix-right">${asker}${active?`<button id="clear" class="strip-control" aria-label="Clear filters" title="Clear filters">${stripIcon('Clear')}<span class="strip-label">Clear</span></button>`:''}<span class="totals" role="status" aria-live="polite"><b class="num">${count}</b> markets</span>${viewSeg()}<a class="primary ix-create" href="#/create">${hIcon('plus')}Create Market</a></div></div>`;}

/* Index table */
const COLS=[[null,'','c-logo'],['name','Market','c-q'],['prob','Leading','c-lead'],[null,'Split','c-mix'],['volume','Volume','c-vol'],['liquidity','Liquidity','c-liq'],['closes','Closes','c-close'],[null,'','c-open']];
function mix(m){const o=outcomes(m),tot=o.reduce((s,x)=>s+x.p,0)||1;return `<span class="mix" role="img" aria-label="${esc(o.map(x=>x.name+' '+pct(x.p)+'%').join(', '))}">${o.slice(0,5).map((x,j)=>`<i style="width:${(x.p/tot*100).toFixed(2)}%" data-j="${j}"></i>`).join('')}</span>`;}
function row(m){const l=lead(m),k=kind(m),st=shortStatus(m);
 return `<div class="ix-row" role="row" tabindex="0" data-id="${m.id}" aria-selected="${state.sel===m.id}"><div class="c-logo" role="cell">${mkImg(m,'ix-av')}</div><div class="c-q" role="cell"><span class="q-title" title="${esc(m.marketName)}">${esc(m.marketName)}</span><span class="q-cap">Asked by <button class="asker-link mono" data-asker="${m.creator}" title="All markets asked by ${m.creator}">${askerLabel(m.creator)}</button></span></div><div class="c-lead" role="cell">${l?`<span class="lead-top"><span class="lead-name" title="${esc(l.name)}">${esc(l.name)}</span><b class="num" title="${esc(l.value)}">${esc(l.value)}</b></span><span class="lead-bar"><i style="width:${pct(clamp(l.p))}%"></i></span>`:'<span class="muted">No price</span>'}</div><div class="c-mix" role="cell">${spark(m)||mix(m)}</div><div class="c-vol num" role="cell">${money(m.volumeUSD)}</div><div class="c-liq num" role="cell">${money(m.liquidityUSD)}</div><div class="c-close num" role="cell" title="Reports open ${date(m.openingTs)}">${rel(m.openingTs)}</div><div class="c-open" role="cell"><a class="ix-open" href="#/market/${m.id}" title="Open full market page" aria-label="Open full market page: ${esc(m.marketName)}">Open${hIcon('arrow')}</a></div></div>`;}
function table(a){return `<div class="ix-table" role="table" aria-label="Markets" aria-rowcount="${a.length+1}"><div class="ix-head" role="row">${COLS.map(([k,l,c])=>`<div class="${c}" role="columnheader"${k&&state.sort===k?` aria-sort="${state.asc?'ascending':'descending'}"`:''}>${k?`<button class="th-sort" data-sort="${k}">${l}<i aria-hidden="true">${state.sort===k?(state.asc?'↑':'↓'):''}</i></button>`:l?`<span class="th-plain">${l}</span>`:`<span class="sr">${c==='c-open'?'Open market':'Logo'}</span>`}</div>`).join('')}</div>${a.map(row).join('')||emptyState()}</div>`;}
function emptyState(){return `<div class="empty-state">${hIcon('search')}<h2>No markets match</h2><p>Try a different question, address or set of filters.</p><button class="soft" id="reset">Clear filters${hIcon('close')}</button></div>`;}
function spark(m){const s=histories.get(m.id);if(!s)return '';const lid=outcomes(m)[0]?.i,pts=(s.get(lid)||[...s.values()][0]||[]);if(pts.length<2)return '';const t0=pts[0].t,t1=pts.at(-1).t,lo=Math.min(...pts.map(p=>p.p)),hi=Math.max(...pts.map(p=>p.p)),pad=Math.max(1,(hi-lo)*.15);const X=t=>(t-t0)/Math.max(1,t1-t0)*72,Y=p=>2+(1-(p-lo+pad)/(hi-lo+2*pad))*24;return `<svg class="spark" viewBox="0 0 72 28" role="img" aria-label="Recorded price history"><path d="${pts.map((p,i)=>`${i?'L':'M'}${X(p.t).toFixed(1)} ${Y(p.p).toFixed(1)}`).join('')}"/></svg>`;}

/* Tiles: equal height, one mini visual per market type */
function miniVisual(m){const o=outcomes(m),k=kind(m);
 if(k==='Conditional'){const p=m.parentMarket&&state.markets.find(x=>x.id===m.parentMarket.id),cond=p?plain(p)[Number(m.parentOutcome)||0]:'parent outcome';const l=lead(m);return `<div class="mv mv-cond"><span class="mv-if" title="${esc('If '+cond)}">If ${esc(cond)}</span><span class="mv-then"><i style="width:${pct(clamp(l?.p))}%"></i></span></div>`;}
 if(k==='Binary'){const y=o.find(x=>/^yes$/i.test(x.name))||o[0];return `<div class="mv mv-split" role="img" aria-label="Yes ${pct(y?.p||0)}%"><i style="width:${pct(clamp(y?.p))}%"></i></div>`;}
 if(k==='Scalar'){const l=lead(m),lo=num(Number(m.lowerBound)/1e18),hi=num(Number(m.upperBound)/1e18);return `<div class="mv mv-range" role="img" aria-label="Estimate ${esc(l?.value||'')} between ${lo} and ${hi}"><span class="num">${lo}</span><span class="mv-track"><i style="left:${pct(clamp(l?.p))}%"></i></span><span class="num">${hi}</span></div>`;}
 return `<div class="mv mv-rank">${o.slice(0,3).map((x,j)=>`<span><em title="${esc(x.name)}">${esc(x.name)}</em><i style="--w:${pct(clamp(x.p))}%" data-j="${j}"></i></span>`).join('')}</div>`;}
function tileCard(m){
 const os=outcomes(m),k=kind(m),verified=m.verification?.status==='verified',conditionalMarket=!!conditional(m);
 const seal=conditionalMarket?'fork':verified?'verified':'caution';
 const sealTitle=[k,shortStatus(m),verified?'Verified':'Not verified',m.incentive>0?'Rewards available':''].filter(Boolean).join(' · ');
 return `<article class="ix-tile" tabindex="0" data-id="${m.id}" aria-selected="${state.sel===m.id}" aria-label="${h(m.marketName)}"><div class="tl-head"><div class="tl-avatar">${mkImg(m,'tl-av')}<span class="tl-seal ${verified?'verified':'unverified'}" title="${h(sealTitle)}" role="img" aria-label="${h(sealTitle)}">${hIcon(seal)}</span></div><h3 class="tl-q" title="${h(m.marketName)}">${h(m.marketName)}</h3><button class="open-trade" data-open-trade="${m.id}" title="Open trade" aria-label="Open trade: ${h(m.marketName)}">${hIcon('arrow')}</button></div><div class="tl-mid">${hMark(m)}${legend(m,'tl-lg')}</div><div class="tl-foot"><span class="q-cap">Asked by <button class="asker-link mono" data-asker="${m.creator}" title="All markets asked by ${m.creator}">${askerLabel(m.creator)}</button><button class="copy-asker" data-copy-asker="${m.creator}" title="Copy asker address" aria-label="Copy asker address: ${m.creator}">${hIcon('copy')}</button></span><span class="num tl-vol" title="Captured traded volume${m.incentive>0?', rewards available':''}">${m.incentive>0?hIcon('star'):''}${money(m.volumeUSD)} <small>vol</small></span></div></article>`;
}
function tiles(a){return a.length?`<div class="ix-tiles">${a.map(tileCard).join('')}</div>`:emptyState();}

/* Activity: real events only (market creation transactions, captured pool prices) */
function activity(a){const ids=new Map(a.map(m=>[m.id,m])),ev=a.map(m=>({t:Number(m.blockTimestamp),m,e:'Created'}));histories.forEach((series,id)=>{const m=ids.get(id);if(!m)return;series.forEach((pts,i)=>{const p=pts.at(-1);if(p)ev.push({t:p.t,m,e:'Price',name:m.outcomes[i]?.trim(),p:p.p});});});ev.sort((x,y)=>y.t-x.t);
 return ev.length?`<div class="ix-table ix-activity" role="table" aria-label="Recent activity"><div class="ix-head" role="row"><div class="a-time" role="columnheader"><span class="th-plain">When</span></div><div class="a-ev" role="columnheader"><span class="th-plain">Event</span></div><div class="c-q" role="columnheader"><span class="th-plain">Market</span></div><div class="a-link" role="columnheader"><span class="th-plain">Record</span></div></div>${ev.slice(0,40).map(x=>`<div class="ix-row" role="row" tabindex="0" data-id="${x.m.id}" aria-selected="${state.sel===x.m.id}"><div class="a-time num" role="cell" title="${date(x.t)}">${rel(x.t)}</div><div class="a-ev" role="cell"><span class="st-chip" data-st="${x.e}">${x.e==='Created'?'Created':'Price'}</span></div><div class="c-q" role="cell"><span class="q-title" title="${esc(x.m.marketName)}">${esc(x.m.marketName)}</span><span class="q-cap">${x.e==='Created'?`Asked by <button class="asker-link mono" data-asker="${x.m.creator}" title="All markets asked by ${x.m.creator}">${askerLabel(x.m.creator)}</button>`:`${esc(x.name)} pool price ${pct(x.p)}%`}</span></div><div class="a-link" role="cell">${x.e==='Created'&&x.m.transactionHash?external(explorer(x.m)+'/tx/'+x.m.transactionHash,'Tx ↗','class="mono" title="Creation transaction"'):date(x.t)}</div></div>`).join('')}</div>`:emptyState();}

/* Detail panel */
function asksLine(m){const o=outcomes(m),k=baseKind(m),l=o[0],n=o.length;
 const base=k==='Binary'?(()=>{const y=o.find(x=>/^yes$/i.test(x.name));return y?`Yes or no. The crowd reads Yes as ${tone(y.p)}, at ${pct(y.p)}%.`:'Yes or no.';})():k==='Scalar'?`A number from ${num(Number(m.lowerBound)/1e18)} to ${num(Number(m.upperBound)/1e18)}. Crowd estimate: ${estimate(m)||'not priced'}.`:k==='Multi-outcome'?(m.templateId==='3'?`Several of ${n} outcomes can be true. Each price is its own chance.`:`Splits a total across ${n} outcomes. ${esc(l?.name||'')} gets the largest share.`):`One of ${n} outcomes wins. ${esc(l?.name||'')} leads at ${pct(l?.p||0)}%.`;
 if(!conditional(m))return base;const p=state.markets.find(x=>x.id===m.parentMarket.id),c=p?plain(p)[Number(m.parentOutcome)||0]:'';return `${base}<br>Counts only if ${c?`“${esc(c)}”`:'the parent outcome'} wins the parent market.`;}

/* Context strip: who asks / what is priced / how to use the signal (Seer article test). Live with the selected market. */
function ctxPriced(m){const k=baseKind(m);if(conditional(m))return k==='Binary'?'the chance of Yes if the parent outcome happens':'the chance of each outcome if the parent outcome happens';return k==='Binary'?'the chance of Yes':k==='Scalar'?'the expected value in the range':k==='Multi-outcome'?(m.templateId==='3'?'the chance each outcome is true':'the share each option takes'):'the chance of each outcome';}
function ctxHow(m){const k=baseKind(m),o=outcomes(m),l=lead(m);return k==='Scalar'?`Read ${l?.value||'the estimate'} as the crowd’s best guess.`:k==='Multi-outcome'&&m.templateId!=='3'?'Read each share as the expected split.':`Read ${pct(o[0]?.p||0)}% as the chance of ${o[0]?.name||'the leader'}. A winning share pays 1.`;}
function ctxRow(){const m=state.listMarkets.find(x=>x.id===state.sel);
 const item=(l,v,t)=>`<p class="sb-item"><b>${l}</b><span${t?` title="${esc(t)}"`:''}>${v}</span></p>`;
 const asked=m?`<button class="asker-link mono ctx-asker" data-asker="${m.creator}" title="All markets asked by ${m.creator}">${askerLabel(m.creator)}</button> <span class="ctx-n">${askerCount(m.creator)} markets</span>`:'DAOs, protocols, people and agents';
 const priced=m?ctxPriced(m):'the chance of each outcome',how=m?ctxHow(m):'read the odds; trading is optional';
 return `<div class="sb-row sb-ctx" aria-label="What this market is for"><div class="sb-meta" data-testid="ctx-strip">${item('Asked by',asked,m?'':'DAOs, protocols, people and agents')}${item('Priced',esc(priced),priced)}${item('How to use',esc(how),how)}</div></div>`;}
function updateCtx(){const el=$('#ctx');if(!el)return;el.innerHTML=ctxRow();el.querySelectorAll('[data-asker]').forEach(b=>b.onclick=()=>setAsker(b.dataset.asker));}
function detailFacts(m){const rows=[];
 if(REALITY[m.chainId])rows.push(['Oracle','Reality.eth']);
 if(chain(m))rows.push(['Chain',chain(m)]);
 if(m.blockTimestamp)rows.push(['Created',date(m.blockTimestamp)]);
 const v=m.verification?.status;rows.push(['Verified',v==='verified'?'Yes':v?String(v).replace(/^./,c=>c.toUpperCase()):'No']);
 return `<dl class="pn-mini">${rows.map(([k,v])=>`<div><dt>${k}</dt><dd title="${esc(v)}">${esc(v)}</dd></div>`).join('')}</dl>`;}
function panelFacts(m){return `<dl class="pn-ctx3"><div><dt>Asked by</dt><dd><button class="asker-link mono" data-asker="${m.creator}" title="All markets asked by ${m.creator}">${askerLabel(m.creator)}</button><span class="pn-sub num">${askerCount(m.creator)} markets</span></dd></div><div><dt>Priced</dt><dd title="${esc(ctxPriced(m))}"><span class="tx">${esc(ctxPriced(m))}</span></dd></div><div><dt>How to use</dt><dd title="${esc(ctxHow(m))}"><span class="tx">${esc(ctxHow(m))}</span></dd></div></dl>`;}
function facts(m){const k=baseKind(m),o=outcomes(m),n=o.length,l=lead(m),u=unitOf(m);
 const priced=k==='Binary'?'The chance of Yes':k==='Scalar'?`The expected value${u?' in '+esc(u):''}`:k==='Multi-outcome'?(m.templateId==='3'?'The chance each outcome is true':'Each outcome’s share of the total'):`The chance of each of ${n} outcomes`;
 const how=k==='Scalar'?`Read ${esc(l?.value||'the estimate')} as the crowd’s best guess.`:k==='Multi-outcome'&&m.templateId!=='3'?'Read each share as the expected split.':`Read ${pct(o[0]?.p||0)}% as the chance of ${esc(o[0]?.name||'the leader')}. A winning share pays 1.`;
 return `<dl class="pn-facts"><div><dt>ASKED BY</dt><dd><button class="asker-link mono pn-asker" data-asker="${m.creator}" title="Show all markets asked by ${m.creator}">${askerLabel(m.creator)}</button><span class="pn-sub num">${askerCount(m.creator)} markets</span></dd></div><div><dt>PRICED</dt><dd>${priced}</dd></div><div><dt>HOW TO USE</dt><dd>${how}</dd></div></dl>`;}
function outcomeList(m){const o=outcomes(m),sel=state.tOut??o[0]?.i,sum=m.odds.reduce((s,v)=>s+(Number(v)||0),0);
 return `<section class="pn-sec"><div class="pn-cap"><span>OUTCOME PRICES</span>${o.normalized?`<span class="pn-note" title="Pool prices summed to ${pct(sum)}%. Shown scaled to 100%.">Normalized</span>`:''}</div><ol class="pn-out">${o.slice(0,8).map((x,j)=>`<li><button data-out="${x.i}" aria-pressed="${sel===x.i}" title="${esc(x.name)}"><span class="o-rank num">${j+1}</span><span class="o-name">${esc(x.name)}</span><span class="o-bar"><i style="width:${pct(clamp(x.p))}%"${j===0?' class="lead"':''}></i></span><b class="num">${pct(x.p)}%</b></button></li>`).join('')}</ol>${o.length>8?`<a class="pn-more" href="#/market/${m.id}">${o.length-8} more outcomes</a>`:''}</section>`;}
function resolution(m){return `<section class="pn-sec"><div class="pn-cap"><span>RESOLUTION</span></div><dl class="pn-dl"><div><dt>Oracle</dt><dd>${external(realityUrl(m),'Reality.eth question ↗')}</dd></div><div><dt>Reports open</dt><dd class="num">${date(m.openingTs)} <span class="pn-sub">${rel(m.openingTs)}</span></dd></div><div><dt>Verification</dt><dd>${external(registry,esc((m.verification?.status||'Not verified').replace(/^./,c=>c.toUpperCase()))+' ↗')}</dd></div><div><dt>Chain</dt><dd>${chain(m)}</dd></div><div><dt>Contract</dt><dd>${external(explorer(m)+'/address/'+m.id,short(m.id)+' ↗','class="mono"')}</dd></div><div><dt>Created</dt><dd class="num">${date(m.blockTimestamp)}</dd></div></dl></section>`;}
function ticket2(m){
 const o=outcomes(m),x=o.find(v=>v.i===(state.tOut??o[0]?.i))||o[0];if(!x)return '';
 const p=Math.max(.001,x.p/100),amt=state.tAmt,buy=state.side==='buy',shares=amt/p,err=hQuickError(amt,buy);
 return `<section class="pn-trade" aria-label="Trade"><div class="pn-odds" role="group" aria-label="Outcome">${top2(m).map((v,k)=>`<button class="odd o${k+1}" data-out="${v.i}" aria-pressed="${v.i===x.i}" title="${h(v.name)}" style="--chance:${v.p}%"><span class="odd-n">${h(v.name)}</span><b class="num">${pct(v.p)}<small>%</small></b><i class="odd-track" aria-hidden="true"><i></i></i></button>`).join('')}</div>${o.indexOf(x)>1?`<p class="tk-other">Selected <b title="${h(x.name)}">${h(x.name)}</b><span class="num">${pct(x.p)}%</span></p>`:''}<div class="seg tk-side" role="group" aria-label="Side">${['buy','sell'].map(v=>`<button data-side2="${v}" aria-pressed="${state.side===v}">${v==='buy'?'Buy':'Sell'}</button>`).join('')}</div><div class="tk-chips" role="group" aria-label="${buy?'Amount to pay':'Shares to sell'}">${[10,50,100,500].map(v=>`<button data-amt="${v}" aria-pressed="${amt===v}" class="num">${v}</button>`).join('')}</div><label class="quick-amount" for="quick-amount"><span>${buy?'Custom amount':'Shares to sell'}</span><input id="quick-amount" class="num" type="number" min="1" max="10000" step="1" inputmode="decimal" value="${amt||''}" aria-describedby="quick-err" aria-invalid="${!!err}"></label><p class="field-error" id="quick-err" role="status">${h(err)}</p><dl class="pn-dl tk-quote">${buy?`<div><dt>You pay</dt><dd class="num quote-num" data-quote-value="${amt}">${num(amt)}</dd></div><div><dt>${scalar(m)?`Pays at ${/^up$/i.test(x.name)?'upper':'lower'} bound`:`Pays if ${h(compactName(x.name))} wins`}</dt><dd class="num quote-num" data-quote-value="${shares}">${num(shares)}</dd></div><div><dt>${scalar(m)?'Max endpoint return':'Est. return'}</dt><dd class="num quote-num">+${num(shares-amt)}</dd></div>`:`<div><dt>You sell</dt><dd class="num">${num(amt)} shares</dd></div><div><dt>You receive, about</dt><dd class="num quote-num">${num(amt*p)}</dd></div><div><dt>Price</dt><dd class="num">${pct(x.p)}%</dd></div>`}</dl><div class="quick-payoff" aria-label="Estimated contingent payout"><span>${buy?'Pay':'Shares'} <b class="num">${num(amt)}</b></span><div aria-hidden="true"><i></i><i style="transform:scaleX(${Math.min(1,p)})"></i></div><span>${buy?'If it wins':'Receive'} <b class="num">${num(buy?shares:amt*p)}</b></span></div><button class="tk-connect" id="tk-connect"${err?' disabled':''}>Preview ${buy?'buy':'sell'} ${h(compactName(x.name))}${hIcon('arrow')}</button><p class="tk-note" id="tk-note" role="status">Demo estimate · No funds move.</p></section>`;
}
function priceJson(m){return {market_id:m.id,question:m.marketName.trim(),type:kind(m),chain_id:m.chainId,as_of:new Date(NOW*1000).toISOString(),prices:outcomes(m).map(o=>({outcome:o.name,probability:Number((o.p/100).toFixed(4))})),normalized:!!outcomes(m).normalized,volume:Math.round(Number(m.volumeUSD)||0),liquidity:Math.round(Number(m.liquidityUSD)||0),reports_open:new Date(m.openingTs*1000).toISOString().slice(0,10),asker:m.creator,oracle:'reality.eth'};}
function agentBody(m){const call=`read_prices({ market_id: "${m.id}" })`,res=JSON.stringify(priceJson(m),null,2);return `<section class="pn-sec pn-agent"><div class="agent-intro">${hIcon('agent')}<div><b>Agent view</b><p>The same captured signal, ready for a tool call.</p></div></div><div class="machine-strip"><code title="${m.id}">${short(m.id)}</code><button data-copy-value="${m.id}" aria-label="Copy market id" title="Copy market id">${hIcon('copy')}</button></div><div class="pn-cap"><span>Tool call</span><span class="pn-sub">Read only</span></div><pre class="code" id="ag-call">${h(call)}</pre><div class="pn-cap"><span>Response</span><span class="pn-sub num">${outcomes(m).length} prices</span></div><pre class="code code-res" id="ag-res">${h(res)}</pre><button class="soft pn-copy" id="ag-copy">${hIcon('copy')}Copy call and response</button></section>`;}
function panel(){
 updateCtx();const el=$('#ix-panel');if(!el)return;
 const m=state.listMarkets.find(x=>x.id===state.sel);
 if(!m){el.innerHTML=`<div class="pn-empty">${hIcon('crosshair')}<b>Select a market</b><span>Read its prices, context and order estimate here.</span></div>`;hSyncPanels();return;}
 const k=kind(m),st=shortStatus(m),open=!!state.details;
 el.innerHTML=`<div class="pn-scroll" tabindex="0" aria-label="Selected market information"><div class="pn-head">${mkImg(m,'pn-av',true)}<h2 class="pn-title" title="${h(m.marketName)}">${h(m.marketName)}</h2><button class="pn-x" id="pn-close" aria-label="Close market detail">${hIcon('close')}</button></div>${panelFacts(m)}${state.agent?agentBody(m):ticket2(m)}${detailFacts(m)}</div><div class="pn-sticky-footer"><div id="pn-order-action"></div><div class="pn-foot"><button class="pn-dt" id="pn-dt" aria-expanded="${open}" aria-controls="pn-details">Details${hIcon('chevron')}</button><button class="soft pn-open" id="pn-open" title="Open full market page">Full page${hIcon('arrow')}</button></div></div><div class="pn-details" id="pn-details" role="region" aria-label="Market details"${open?'':' hidden'}><div class="pn-dhead"><b>Details</b><button class="pn-x pn-dx" id="pn-dx" aria-label="Close details">${hIcon('close')}</button></div><div class="pn-dbody"><div class="pn-chips"><span class="type-pill" data-kind="${k}">${k}</span><span class="st-chip" data-st="${st}" title="${h(status(m))}">${st}</span></div><div class="pn-asks"><span class="pn-cap"><span>What this market asks</span></span><p>${asksLine(m)}</p></div>${outcomeList(m)}${chartBlock(m)}${resolution(m)}</div></div>`;
 const action=$('#pn-order-action',el),cta=$('#tk-connect',el),note=$('#tk-note',el);if(cta)action.append(cta);if(note)action.append(note);if(state.agent)action.hidden=true;
 for(const child of el.children)child.inert=open&&!child.classList.contains('pn-details');
 wirePanel(m);hWireQuickAmount(m);hSyncPanels();hSyntax(el);hSegment(el);hUpgradeIcons(el);hRollQuick();
}
function wirePanel(m){const el=$('#ix-panel');
 $('#pn-open',el).onclick=()=>{location.hash='#/market/'+m.id;};$('#pn-close',el).onclick=closeSheet;
 const setD=v=>{state.details=v;repaint();(v?$('#pn-dx',el):$('#pn-dt',el))?.focus({preventScroll:true});};$('#pn-dt',el).onclick=()=>setD(!state.details);$('#pn-dx',el).onclick=()=>setD(false);el.onkeydown=e=>{if(e.key==='Escape'&&state.details){e.stopPropagation();setD(false);}};
 el.querySelectorAll('[data-asker]').forEach(b=>b.onclick=()=>setAsker(b.dataset.asker));
 el.querySelectorAll('[data-out]').forEach(b=>b.onclick=()=>{state.tOut=Number(b.dataset.out);repaint();});
 el.querySelectorAll('[data-side2]').forEach(b=>b.onclick=()=>{state.side=b.dataset.side2;repaint();});
 el.querySelectorAll('[data-amt]').forEach(b=>b.onclick=()=>{state.tAmt=Number(b.dataset.amt);repaint();});
 
 $('#tk-connect',el)?.addEventListener('click',()=>{const o=outcomes(m),x=o.find(v=>v.i===(state.tOut??o[0]?.i))||o[0];if(!x)return;const p=Math.max(.001,x.p/100),a=state.tAmt,sell=state.side==='sell',err=sell?'':amountError(a);if(err){const n=$('#tk-note',el);n.textContent=err;n.classList.add('err');return;}confirmTrade({m,name:compactName(x.name),sell,pay:a,get:sell?a*p:a/p,avg:p});});
 $('#ag-copy',el)?.addEventListener('click',async()=>{const s=$('#ag-call').textContent+'\n\n'+$('#ag-res').textContent;try{await navigator.clipboard.writeText(s);toast('Copied call and response');}catch{modal('Copy',`<textarea style="width:100%;height:240px">${h(s)}</textarea>`);}});
 wirePanelChart(m);
 function repaint(){const top=$('.pn-dbody',el)?.scrollTop||0,f=document.activeElement?.closest('#ix-panel')?(document.activeElement.dataset.out!=null?`[data-out="${document.activeElement.dataset.out}"]`:document.activeElement.dataset.side2?`[data-side2="${document.activeElement.dataset.side2}"]`:document.activeElement.dataset.amt?`[data-amt="${document.activeElement.dataset.amt}"]`:null):null;panel();const db=$('.pn-dbody',el);if(db)db.scrollTop=top;if(f)$(f,el)?.focus({preventScroll:true});}}

/* Detail chart: one series (the leading outcome), auto-zoomed, crosshair on hover and keys */
function chartBlock(m){const s=histories.get(m.id);if(!s)return '';return `<section class="pn-sec"><div class="pn-cap"><span>PRICE HISTORY</span><div class="seg pn-ranges" role="group" aria-label="Range">${['1D','1W','1M','All'].map(r=>`<button data-prange="${r}" aria-pressed="${state.range===r}">${r}</button>`).join('')}</div></div><div class="pn-chart" id="pn-chart" tabindex="0" role="img" aria-label="Price history. Use arrow keys to read points."></div></section>`;}
function chartSeries(m){const s=histories.get(m.id);if(!s)return null;const o=outcomes(m);const top=o.find(x=>s.has(x.i))||null;if(!top)return null;const all=s.get(top.i);if(!all?.length)return null;const end=all.at(-1).t,start=state.range==='All'?all[0].t:end-({'1D':86400,'1W':604800,'1M':2592000}[state.range]);const pts=all.filter(p=>p.t>=start);return {name:top.name,pts:pts.length?pts:[all.at(-1)]};}
function wirePanelChart(m){const host=$('#pn-chart');if(!host)return;document.querySelectorAll('[data-prange]').forEach(b=>b.onclick=()=>{state.range=b.dataset.prange;document.querySelectorAll('[data-prange]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));draw();});
 let idx=-1,data=null;
 function draw(){data=chartSeries(m);const W=Math.max(200,Math.round(host.clientWidth)),H=232,L=8,Rt=56,T=12,B=24;if(!data){host.innerHTML='<p class="pn-sub">No recorded prices in this range</p>';return;}
  const pts=data.pts,t0=pts[0].t,t1=pts.at(-1).t,lo0=Math.min(...pts.map(p=>p.p)),hi0=Math.max(...pts.map(p=>p.p)),pad=Math.max(2,(hi0-lo0)*.08),lo=Math.max(0,lo0-pad),hi=Math.min(100,hi0+pad);
  const X=t=>L+(t1===t0?(W-L-Rt)/2:(t-t0)/(t1-t0)*(W-L-Rt)),Y=p=>T+(1-(p-lo)/Math.max(.001,hi-lo))*(H-T-B);
  const line=pts.map((p,i)=>`${i?'L':'M'}${X(p.t).toFixed(1)} ${Y(p.p).toFixed(1)}`).join('');const last=pts.at(-1);
  host.__pts=pts.map(p=>({x:X(p.t),y:Y(p.p),p:p.p,t:p.t}));
  host.innerHTML=`<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">${[.25,.5,.75].map(f=>`<path class="guide" d="M${L} ${(T+f*(H-T-B)).toFixed(1)}H${W-Rt}"/>`).join('')}${pts.length>1?`<path d="${line}L${X(last.t)} ${H-B}L${X(t0)} ${H-B}Z" fill="var(--o1)" opacity=".08"/>`:''}<path class="ln" d="${line}"/><circle class="end" cx="${X(last.t)}" cy="${Y(last.p)}" r="3.5"/><text class="end-lbl halo" x="${X(last.t)+8}" y="${Y(last.p)+4}">${pct(last.p)}%</text><text class="end-lbl" x="${X(last.t)+8}" y="${Y(last.p)+4}">${pct(last.p)}%</text><text class="ax" x="${L}" y="${H-6}">${date(t0)}</text><text class="ax" x="${W-Rt}" y="${H-6}" text-anchor="end">${date(t1)}</text><text class="ax" x="${W-4}" y="${T+8}" text-anchor="end">${pct(hi)}%</text><text class="ax" x="${W-4}" y="${H-B}" text-anchor="end">${pct(lo)}%</text><g class="xh" id="pn-xh" visibility="hidden"><path d="M0 ${T}V${H-B}"/><circle r="4"/></g></svg><div class="pn-tip" id="pn-tip" role="status" hidden></div><span class="pn-series">${esc(data.name)}</span>`;idx=-1;}
 function show(i){const P=host.__pts;if(!P?.length)return;idx=Math.max(0,Math.min(P.length-1,i));const p=P[idx],g=$('#pn-xh',host),tip=$('#pn-tip',host);g.setAttribute('visibility','visible');$('path',g).setAttribute('transform',`translate(${p.x} 0)`);$('circle',g).setAttribute('cx',p.x);$('circle',g).setAttribute('cy',p.y);tip.hidden=false;tip.textContent=`${pct(p.p)}% · ${new Date(p.t*1000).toLocaleString('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'UTC'})} UTC`;const w=tip.offsetWidth;tip.style.left=Math.max(0,Math.min(host.clientWidth-w,p.x-w/2))+'px';}
 function hide(){const g=$('#pn-xh',host);g?.setAttribute('visibility','hidden');const t=$('#pn-tip',host);if(t)t.hidden=true;}
 host.onpointermove=e=>{const P=host.__pts;if(!P)return;const x=e.clientX-host.getBoundingClientRect().left;let b=0;P.forEach((p,i)=>{if(Math.abs(p.x-x)<Math.abs(P[b].x-x))b=i;});show(b);};host.onpointerleave=hide;host.onblur=hide;
 host.onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();show(idx<0?(host.__pts.length-1):idx+(e.key==='ArrowRight'?1:-1));}};
 draw();}

/* Selection, sheet, filters */
function select(id,from){state.sel=id;state.tOut=null;state.details=false;state.side='buy';document.querySelectorAll('.ix-row,.ix-tile').forEach(r=>r.setAttribute('aria-selected',String(r.dataset.id===id)));markFan();panel();writeQuery();if(!desktop())openSheet();}
function openSheet(){const p=$('#ix-panel');if(!p)return;state.sheetFrom=document.activeElement;p.setAttribute('role','dialog');p.setAttribute('aria-modal','true');p.classList.add('open');p.inert=false;$('#ix-scrim').hidden=false;document.body.classList.add('sheet-open');$('#pn-close')?.focus({preventScroll:true});}
function closeSheet(){const p=$('#ix-panel');if(!p||!p.classList.contains('open'))return;p.classList.remove('open');p.removeAttribute('role');p.removeAttribute('aria-modal');if(!desktop())p.inert=true;$('#ix-scrim').hidden=true;document.body.classList.remove('sheet-open');state.sheetFrom?.focus?.({preventScroll:true});}
function setAsker(a){state.asker=(a||'').toLowerCase();closeSheet();update();$('.ix-main')?.scrollIntoView({block:'start',behavior:reduced()?'auto':'smooth'});}
function resetFilters(){state.filters={};state.query='';state.asker='';state.conditional=state.rewards=false;state.minLiquidity=0;const s=$('#search');if(s)s.value='';update();}
function filterMenu(b){const k=b.dataset.filter;
 if(k==='Advanced'){menu(b,`<div class="menu-title">Market properties</div><div class="advanced">${[['rewards','Rewards only']].map(([key,label])=>`<label><span>${label}</span><input type="checkbox" data-toggle="${key}" ${state[key]?'checked':''}></label>`).join('')}<label for="min-liquidity">Minimum liquidity</label><input id="min-liquidity" type="number" min="0" step="100" value="${state.minLiquidity||0}"><button class="primary" id="apply-advanced">Apply filters</button></div>`);$('#apply-advanced').onclick=()=>{pop.querySelectorAll('[data-toggle]').forEach(n=>state[n.dataset.toggle]=n.checked);state.minLiquidity=Math.max(0,Number($('#min-liquidity').value)||0);closeMenu(false);update();$('[data-filter=Advanced]')?.focus();};return;}
 if(k==='Sort'){menu(b,`<div class="menu-title">Sort markets</div><div class="option-list">${SORT_LABELS.map(([v,l])=>`<button data-option="${v}" aria-pressed="${state.sort===v}"><span>${l}</span><span class="check">${state.sort===v?'✓':''}</span></button>`).join('')}</div><div class="sort-direction"><button data-dir="asc" aria-pressed="${state.asc}">↑ Ascending</button><button data-dir="desc" aria-pressed="${!state.asc}">↓ Descending</button></div>`);pop.querySelectorAll('[data-option]').forEach(o=>o.onclick=()=>{state.sort=o.dataset.option;state.asc=!!ASC_DEFAULT[state.sort];closeMenu(false);update();$('[data-filter=Sort]')?.focus();});pop.querySelectorAll('[data-dir]').forEach(o=>o.onclick=()=>{state.asc=o.dataset.dir==='asc';closeMenu(false);update();$('[data-filter=Sort]')?.focus();});return;}
 const opts=k==='Topic'?['All',...new Set(state.listMarkets.flatMap(m=>m.categories))]:filterOptions[k];const cur=state.filters[k]||'All';
 menu(b,`<div class="menu-title">${k==='Verified'?'Verification':k}</div><div class="option-list">${opts.map(v=>`<button data-option="${esc(v)}" aria-pressed="${cur===v}"><span>${esc(v)}</span><small>${state.listMarkets.filter(m=>matches(m,k,v)).length}</small><span class="check">${cur===v?'✓':''}</span></button>`).join('')}</div>`);
 pop.querySelectorAll('[data-option]').forEach(o=>o.onclick=()=>{if(o.dataset.option==='All')delete state.filters[k];else state.filters[k]=o.dataset.option;closeMenu(false);update();$(`[data-filter="${k}"]`)?.focus();});}

function home(){closeMenu(false);app.innerHTML=`<div class="sb ctx-static" id="ctx">${ctxRow()}</div><div class="ix">${hero()}<div class="ix-layout"><section class="ix-main" aria-label="Markets" data-align><div id="ix-tools"></div><div id="ix-body"></div><footer class="footer ix-foot"><span>Seer Explorer</span><span>Sample data · Oct 18, 2026</span></footer></section><div class="ix-scrim" id="ix-scrim" hidden></div><aside class="ix-panel" id="ix-panel" aria-label="Market detail" data-overlay></aside></div></div>`;
 $('#ix-scrim').onclick=closeSheet;
 wireHero();updateCtx();
 if(!desktop())$('#ix-panel').inert=true;
 update();}
function update(){if(!$('#ix-body'))return;const a=filtered();
 if(desktop()&&(!state.sel||!state.listMarkets.some(m=>m.id===state.sel)))state.sel=a[0]?.id||'';
 $('#ix-tools').innerHTML=toolsRow(a.length);
 $('#ix-body').innerHTML=state.view==='tiles'?tiles(a):state.view==='activity'?activity(a):a.length?table(a):emptyState();
 const tools=$('#ix-tools');
 tools.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;update();tools.querySelector(`[data-view="${b.dataset.view}"]`)?.focus();});
 tools.querySelectorAll('[data-filter]').forEach(b=>hoverMenu(b,()=>filterMenu(b)));
 $('#clear')?.addEventListener('click',resetFilters);$('#reset')?.addEventListener('click',resetFilters);
 tools.querySelector('[data-clear-asker]')?.addEventListener('click',()=>{state.asker='';update();});
 const body=$('#ix-body');
 body.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{const k=b.dataset.sort;state.asc=state.sort===k?!state.asc:!!ASC_DEFAULT[k];state.sort=k;update();$(`[data-sort="${k}"]`)?.focus();});
 body.querySelectorAll('[data-asker]').forEach(b=>b.onclick=e=>{e.stopPropagation();setAsker(b.dataset.asker);});
 body.querySelectorAll('.ix-row[data-id],.ix-tile').forEach(r=>{r.onclick=e=>{if(e.target.closest('a,button'))return;select(r.dataset.id);};r.ondblclick=e=>{if(e.target.closest('a,button'))return;location.hash='#/market/'+r.dataset.id;};
  r.onkeydown=e=>{if(e.target!==r)return;if(e.key==='Enter'){location.hash='#/market/'+r.dataset.id;}else if(e.key===' '){e.preventDefault();select(r.dataset.id);}else if(e.key==='ArrowDown'||e.key==='ArrowUp'||(state.view==='tiles'&&(e.key==='ArrowRight'||e.key==='ArrowLeft'))){e.preventDefault();const all=[...body.querySelectorAll('.ix-row[data-id],.ix-tile')],i=all.indexOf(r),n=all[i+(e.key==='ArrowDown'||e.key==='ArrowRight'?1:-1)];if(n){n.focus();if(desktop())select(n.dataset.id);}}};});
 panel();drawFan();writeQuery();hSyncPanels();hSegment();}
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
function market(m){const os=sides(m);if(!os.some(o=>o.i===state.selected))state.selected=os[0]?.i??0;app.innerHTML=`<div class="market-layout"><section class="market-content">${marketHeader(m)}<h1 class="market-title">${esc(m.marketName)}</h1><div class="market-meta"><div><small>Liquidity</small><strong>${money(m.liquidityUSD)}</strong></div><div><small>Traded</small><strong>${money(m.volumeUSD)}</strong></div><div><small>Open interest</small><strong>${money(m.openInterestUSD)}</strong></div><div><small>Market type</small><strong>${type(m)}</strong></div></div><div class="chart-card"><div class="chart-head"><h2>What the market thinks</h2><button id="export" aria-label="Export current prices">↓ CSV</button></div><div id="winning-chart">${winningChart(m)}</div></div><div class="information"><p><b>WHO</b><span>Asked by <a class="mono" href="${explorer(m)}/address/${m.creator}" target="_blank" rel="noopener noreferrer">${askerLabel(m.creator)} ↗</a> · ${esc(m.verification?.status||'Unverified')}</span></p><p><b>WHAT</b><span>${esc(m.marketName)}</span></p><p><b>HOW</b><span>${scalar(m)?`Market estimate: ${h(estimate(m))}. Scalar shares settle proportionally between the lower and upper bounds.`:`${outcomes(m)[0]?`${esc(outcomes(m)[0].name)} is priced at ${pct(outcomes(m)[0].p)}%. `:''}A winning share pays one unit.`}</span></p></div><div class="section-title"><h2>Outcomes <small>${m.outcomes.length}</small></h2><a class="meta" href="https://app.seer.pm/markets/${m.chainId}/${m.url}" target="_blank" rel="noopener noreferrer">Open live market ↗</a></div><div>${outcomes(m).map((o,j)=>`<div class="outcome-row"><span style="color:${color(o,j)}">${esc(o.name)}</span><b>${pct(o.p)}%</b><button class="buy ${j===0?'yes':'no'}" data-select="${o.i}" aria-label="Buy ${esc(o.name)}">Buy ${esc(compactName(o.name))}</button><div class="bar"><span class="${j===1?'hatch2':''}" style="width:${pct(Math.min(o.p,100))}%;${j===1?'':'background:'+color(o,j)}"></span></div></div>`).join('')}</div><div class="tabs">${['Information','Pools','Related','Agent JSON'].map(t=>`<button data-tab="${t}" class="${state.tab===t?'active':''}">${t}</button>`).join('')}</div><div class="tab-content" id="tab-content"></div><footer class="footer"><a href="#/">← All markets</a><span>Sample data · Oct 18, 2026</span></footer></section><aside class="trade" aria-label="Order console"><div class="trade-wallet trade-top"><span class="trade-chain">${hIcon('chain')}${chain(m)}</span><span>Order preview</span><button class="trade-close" aria-label="Close order console">×</button></div><div class="trade-body" id="trade-body"></div><div class="trade-cta trade-bottom"><p class="tr-err" id="tr-err" role="alert"></p><button class="primary tr-go" id="tr-go">Connect wallet to trade</button><div class="tr-foot trade-foot"><span class="trade-note">Estimate before fees.</span>${external("https://app.seer.pm/markets/"+m.chainId+"/"+m.url,"Open on seer.pm ↗",'class="tr-ext"')}</div></div></aside></div><button class="mobile-trade primary" id="mobile-trade">Open order console ↑</button>`;
document.querySelector('[data-topic]')?.addEventListener('click',e=>{state.filters.Topic=e.currentTarget.dataset.topic;});$('.trade-close').onclick=()=>toggleConsole(false);$('#mobile-trade').setAttribute('aria-expanded','false');$('#mobile-trade').onclick=()=>toggleConsole(!$('.trade').classList.contains('open'));$('#export').onclick=()=>{const blob=new Blob(['Outcome,Probability\n'+outcomes(m).map(o=>`"${o.name.replace(/"/g,'""')}",${o.p}`).join('\n')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`seer-${m.id}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{state.selected=Number(b.dataset.select);ticket(m);if(innerWidth<1051)toggleConsole(true);});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));tab(m);hSyntax();hSegment();});ticket(m);tab(m);wireChart(m);hSyncPanels();hSyntax();hSegment();if(state.openTrade&&innerWidth<1051)toggleConsole(true);state.openTrade=false;}
function tab(m){let html='';if(state.tab==='Information')html=`<div class="detail-list"><div><span>Question opens</span><span>${date(m.openingTs)}</span></div><div><span>Created</span><span>${date(m.blockTimestamp)}</span></div><div><span>Creator</span>${external(explorer(m)+'/address/'+m.creator,askerLabel(m.creator),'class="mono"')}</div><div><span>Verification</span>${external(registry,esc(m.verification?.status))}</div><div><span>Market contract</span><a class="mono" href="${explorer(m)}/address/${m.id}" target="_blank" rel="noopener noreferrer">${short(m.id)} ↗</a></div><div><span>Outcomes</span><span>${esc(m.outcomes.join(' · '))}</span></div></div>`;else if(state.tab==='Pools')html=`<div class="pool-list">${m.poolBalance.filter(Boolean).map(p=>`<div class="pool-row"><span class="pool-label">Pool balances</span><span class="pool-values num">${num(p.token0.balance)} / ${num(p.token1.balance)}</span>${external('https://app.seer.pm/markets/'+m.chainId+'/'+m.url,`View pool details${hIcon('arrow')}`,'class="pool-action"')}</div>`).join('')}</div>`;else if(state.tab==='Related')html=`<div class="related-list">${state.markets.filter(x=>x.id!==m.id&&x.creator===m.creator).slice(0,12).map(x=>`<a href="#/market/${x.id}"><span>${esc(x.marketName)}</span>${hIcon('arrow')}</a>`).join('')}</div>`;else html=`<pre class="agent-code">${esc(JSON.stringify(signal(m),null,2))}</pre><button id="copy-signal" class="soft">Copy JSON</button>`;$('#tab-content').innerHTML=html;$('#copy-signal')?.addEventListener('click',()=>copy(JSON.stringify(signal(m),null,2)));}
function signal(m){return {market:m.id,question:m.marketName,chainId:m.chainId,creator:m.creator,outcomes:outcomes(m),liquidityUSD:m.liquidityUSD,volumeUSD:m.volumeUSD,verification:m.verification?.status};}
async function copy(s){try{await navigator.clipboard.writeText(s);toast('Copied JSON');}catch{modal('Signal JSON',`<textarea style="width:100%;height:240px">${esc(s)}</textarea>`);}}
/* Full market page order console: live balance scale, rolling Pay/Get, in-app trade */
const SCALE_MAX=1000;
function ticket(m){if($('#payoff-strip')){$('#payoff-strip').innerHTML=payoffStrip(m);animateInstrument($('#payoff-strip'));}const os=sides(m);const o=os.find(x=>x.i===state.selected)||os[0];const idx=Math.max(0,os.indexOf(o)),p=o?Math.max(.001,o.p/100):0;const getLeft=idx===0;sc.getLeft=getLeft;sc.oc=idx;
 const val=(get)=>`<div class="sc-v${get?' get':''}"><span>${get?(scalar(m)?`Get at ${/^up$/i.test(o?.name||'')?'upper':'lower'} bound`:`Get if ${esc(compactName(o?.name||''))} wins`):'Pay'}</span><b class="rn num" id="${get?'win-value':'pay-value'}"></b></div>`;
 $('#trade-body').innerHTML=`<div class="console-title"><b>DEMO ORDER ESTIMATE</b><span class="meta" title="${esc(o?.name||'')}">${o?esc(o.name):'Outcomes'}</span></div><div class="tr-sides" role="group" aria-label="Outcome">${os.slice(0,2).map((x,i)=>`<button data-side="${x.i}" aria-pressed="${x.i===o?.i}" class="tr-side o${i+1}" title="${esc(x.name)}"><span>${esc(x.name)}</span><b class="num">${pct(x.p)}%</b></button>`).join('')}</div>${scaleSvg(getLeft,idx)}<div class="sc-vals">${val(getLeft)}${val(!getLeft)}</div><div class="amount-box"><div class="amt-top"><label for="amount">You pay</label><span class="amt-bal num" id="amt-bal"></span></div><input id="amount" type="number" min="${MIN_AMT}" max="${MAX_AMT}" step="1" value="${state.amount}" inputmode="decimal" aria-describedby="tr-err"><div class="quick-adds">${[1,5,20,100].map(n=>`<button data-add="${n}" class="num">+${n}</button>`).join('')}</div></div><input type="range" id="amount-slider" min="0" max="1000" value="${Math.log10(Math.max(1,state.amount))*250}" aria-label="Order amount"><dl class="quote" id="quote"></dl><details class="tr-more"><summary>Details</summary><dl class="quote" id="quote-more"></dl><label class="slippage">Max slippage<select id="slippage" aria-label="Max slippage">${[0.5,1,2,5].map(n=>`<option>${pct(n)}%</option>`).join('')}</select></label><div class="tr-actions">${['Mint','Merge','Redeem'].map(x=>`<button data-action="${x}" class="soft">${x} ↗</button>`).join('')}</div></details>${state.agent?`<div class="eyebrow">Agent order (JSON)</div><pre class="agent-code" id="order-json"></pre><button id="copy-order" class="soft">Copy order JSON</button>`:''}`;
 placeScale();hSyncPanels();
 const update=()=>{const raw=$('#amount').value.trim();state.amount=raw===''?0:Math.max(0,Number(raw)||0);const amt=Math.min(MAX_AMT,state.amount);const sl=$('#amount-slider');sl.value=Math.log10(Math.max(1,amt))*250;sl.style.setProperty('--fill',pct(sl.value/10)+'%');const L=Math.max(m.liquidityUSD||0,1);const price=a=>Math.min(.999,Math.max(.001,1/(1+Math.exp(-(Math.log(p/Math.max(.001,1-p))+a/(4*L))))));const after=price(amt),avg=(p+after)/2,shares=amt>0?amt/avg:0;
  state.q={m,name:compactName(o?.name||'selected outcome'),sell:false,pay:state.amount,get:shares,avg};
  $('#quote').innerHTML=[['Avg price',num(avg*100)],[scalar(m)?'Max endpoint return':'Potential return',(shares-amt>=0?'+':'−')+num(Math.abs(shares-amt))]].map(([a,b])=>`<div><dt>${a}</dt><dd class="num">${b}</dd></div>`).join('');
  $('#quote-more').innerHTML=[['Price after',num(after*100)],['Shares',num(shares)],['Fees, est.',num(amt*FEE)]].map(([a,b])=>`<div><dt>${a}</dt><dd class="num">${b}</dd></div>`).join('');
  rollTo($('#pay-value'),Math.round(amt).toLocaleString('en-US'));rollTo($('#win-value'),shares.toLocaleString('en-US',{minimumFractionDigits:1,maximumFractionDigits:1}));
  scaleTo(amt,shares);setCta();
  if(state.agent)$('#order-json').textContent=JSON.stringify({market:m.id,outcome:o?.name,amount:amt,slippage:$('#slippage').value},null,2);};
 $('#amount').oninput=update;$('#amount-slider').oninput=e=>{$('#amount').value=Math.round(10**(Number(e.target.value)/250));update();};document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{$('#amount').value=Math.min(MAX_AMT*10,Math.round(state.amount)+Number(b.dataset.add));update();});document.querySelectorAll('.trade [data-side]').forEach(b=>b.onclick=()=>{state.selected=Number(b.dataset.side);ticket(m);$(`.trade [data-side="${b.dataset.side}"]`)?.focus({preventScroll:true});});$('#slippage').onchange=()=>{update();toast(`Max slippage ${$('#slippage').value}`);};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>modal(b.dataset.action,`<p>${esc(m.marketName)}</p><a href="https://app.seer.pm/markets/${m.chainId}/${m.url}" target="_blank" rel="noopener noreferrer">${b.dataset.action} on seer.pm ↗</a>`));$('#copy-order')?.addEventListener('click',()=>copy($('#order-json').textContent));
 const go=$('#tr-go');if(go)go.onclick=()=>{const q=state.q,err=amountError(q?.pay);if(err){setCta(true);$('#amount')?.focus();return;}confirmTrade(q);};
 update();}

function render(){document.body.classList.remove('console-open');closeMenu(false);closeSheet();document.body.classList.toggle('agent',state.agent);const r=route();document.querySelectorAll('[data-route]').forEach(a=>{const active=a.dataset.route===(r==='#/leaderboard'?'leaderboard':(isHome()||r.startsWith('#/market/'))?'markets':'');a.classList.toggle('current',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});app.classList.remove('route-enter');void app.offsetWidth;app.classList.add('route-enter');if(r==='#/leaderboard'){leaderboard();return;}if(r==='#/create'){create();return;}if(r==='#/policies'){policies();return;}if(r.startsWith('#/market/')){const id=decodeURIComponent(r.replace('#/market/',''));const m=state.markets.find(m=>m.id===id);if(m)market(m);else app.innerHTML='<div class="empty">Market not found <a href="#/">All markets →</a></div>';return;}readQuery();home();}
document.addEventListener('keydown',e=>{if(!location.hash.startsWith('#/market/')||!/ArrowUp|ArrowDown/.test(e.key)||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||!pop.hidden||dialog.open)return;e.preventDefault();const list=filtered();const i=list.findIndex(m=>location.hash.endsWith(m.id));const m=list[(i+(e.key==='ArrowDown'?1:-1)+list.length)%list.length];if(m)location.hash='#/market/'+m.id;});
window.addEventListener('hashchange',()=>{state.tab='Information';render();if(!isHome())window.scrollTo(0,0);});
try{document.documentElement.dataset.theme=localStorage.getItem('seer.theme')||localStorage.getItem('seer-theme')||localStorage.getItem('deck.theme')||'dark';}catch{document.documentElement.dataset.theme='dark';}
window.addEventListener('seer:theme',e=>{const t=e.detail&&e.detail.theme==='light'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('deck.theme',t);}catch(_){}if(isHome()&&$('#ix-body')){update();}});

fetch('./data/markets.json').then(r=>{if(!r.ok)throw Error('data');return r.json();}).then(data=>{prepareMarkets(data);normalizeLegacyRoute();return loadHistory().then(()=>{header();render();});}).catch(e=>{console.warn(e);app.innerHTML='<div class="empty">Could not load markets. <button onclick="location.reload()">Retry</button></div>';});
addEventListener('resize',()=>{const p=$('#ix-panel');if(!p)return;if(desktop()){p.inert=false;p.classList.remove('open');$('#ix-scrim').hidden=true;document.body.classList.remove('sheet-open');}else if(!p.classList.contains('open'))p.inert=true;});

function policies(){app.innerHTML=`<section class="create-view policies-view"><a class="meta" href="#/">← Markets</a><div class="create-heading"><h1>Market policies</h1></div><h2 id="verified-market">Verified Market policy</h2><p class="policy-text">A market is marked Verified when its question, outcomes and resolution source are clear, and it follows the Market Rules. Unverified markets can still be read here, but the question may be vague or the source weak. Check the mark before relying on a price.</p><h2 id="market-rules">Market Rules</h2><ul class="policy-list"><li>The question must have one clear answer by a stated date.</li><li>Outcomes must not overlap, and a market that cannot be resolved is settled as Invalid.</li><li>The resolution source must be public and checkable.</li><li>Markets that promote harm, or that can be settled by their creator alone, are not accepted.</li></ul><p class="wallet-note">Full policy text lives on Seer.</p><div class="create-bottom"><a href="#/">Back to markets</a>${policyLinks().split('</a>').slice(1).join('</a>')}</div></section>`;}
let createStep=1;
function create(){createStep=1;drawCreate();}
function drawCreate(){const two=createStep===2;const types=['Categorical','Multi categorical','Scalar','Multi scalar'];const desc={Categorical:'One outcome wins','Multi categorical':'Multiple outcomes may win',Scalar:'A numeric result within a range','Multi scalar':'Numeric results across several outcomes'};
const body=two?`<fieldset disabled class="create-preview"><legend>${esc(state.createType||'Categorical')} market (preview)</legend><label class="field">Question<input type="text" placeholder="Will ... happen by ...?" disabled></label><label class="field">Outcomes<input type="text" placeholder="Yes, No" disabled></label><div class="field-row"><label class="field">Opening date<input type="text" placeholder="YYYY-MM-DD" disabled></label><label class="field">Closing date<input type="text" placeholder="YYYY-MM-DD" disabled></label></div><label class="field">Resolution source<input type="text" placeholder="https://" disabled></label></fieldset><div class="wallet-note">Creating markets happens on Seer</div>`:`<fieldset><legend>Type</legend>${types.map(t=>`<label class="type-choice"><input type="radio" name="market-type" value="${t}"${state.createType===t?' checked':''}><span><b>${t}</b><small>${esc(desc[t])}</small></span></label>`).join('')}</fieldset><div class="wallet-note">Choose a type, then Next shows what a market needs.</div>`;
app.innerHTML=`<section class="create-view"><a class="meta" href="#/">← Markets</a><div class="create-heading"><span class="eyebrow">STEP ${createStep} OF 2</span><h1>Create market</h1><div class="create-steps" aria-label="Step ${createStep} of 2"><span class="current"></span><span${two?' class="current"':''}></span></div></div>${body}<div class="create-bottom">${two?'<button id="create-back" class="link">Back</button>':'<a href="#/">Cancel</a>'}<button class="primary" id="create-next"${!two&&!state.createType?' disabled title="Choose a market type"':''}>${two?'Open on Seer':'Next'}</button></div></section>`;
document.querySelectorAll('[name="market-type"]').forEach(n=>n.onchange=()=>{state.createType=n.value;$('#create-next').disabled=false;$('#create-next').title='';});
$('#create-next').onclick=()=>{if(!two){createStep=2;drawCreate();$('#create-next').focus();}else openOnSeer();};
if(two)$('#create-back').onclick=()=>{createStep=1;drawCreate();};}
function openOnSeer(){modal('Open on Seer','<p>Creating markets happens on Seer, where you connect your wallet on Gnosis and fill in the question, outcomes, dates and resolution source.</p><a href="https://app.seer.pm" target="_blank" rel="noopener noreferrer">Open on Seer ↗</a>');}

const histories=new Map();
async function loadHistory(){await Promise.all(['market-chart','markets-charts'].map(async name=>{try{const response=await fetch('./data/'+name+'.json');if(!response.ok)return;const fixture=await response.json();const raw=fixture.data?._raw_truncated;if(!raw)return;const endpointId=fixture._endpoint.match(/marketId=(0x[0-9a-f]+)/i)?.[1];
// Recover only complete JSON observations. The unfinished final object is ignored.
for(const match of raw.matchAll(/\{"pool":\{.*?"periodStartUnix":\d+\}/g)){let row;try{row=JSON.parse(match[0]);}catch{continue;}const market=state.markets.find(m=>(!endpointId||m.id===endpointId)&&m.wrappedTokens?.some(t=>[row.pool.token0.id,row.pool.token1.id].includes(t)));if(!market)continue;const index=market.wrappedTokens.findIndex(t=>t===row.pool.token0.id||t===row.pool.token1.id);const outcomeIs0=market.wrappedTokens[index]===row.pool.token0.id;const price=Number(outcomeIs0?row.token1Price:row.token0Price)*100;if(!Number.isFinite(price)||price<0||price>100)continue;let series=histories.get(market.id);if(!series){series=new Map();histories.set(market.id,series);}if(!series.has(index))series.set(index,[]);series.get(index).push({t:Number(row.periodStartUnix),p:price});}
}catch{/* Missing history leaves the honest snapshot visible. */}}));histories.forEach(series=>series.forEach(points=>points.sort((a,b)=>a.t-b.t)));}

function marketHeader(m){const opening=Number(m.openingTs),days=Math.ceil((opening-NOW)/86400);const st=status(m)==='Reports not open yet'?'Trading open':status(m);return `<div class="market-heading"><div class="breadcrumb"><a href="#/">Markets</a><span>/</span><a href="#/?topic=${encodeURIComponent(m.categories[0]||'misc')}" data-topic="${esc(m.categories[0]||'misc')}">${esc(m.categories[0]||'misc')}</a><span>/</span><span class="crumb-title" title="${esc(m.marketName)}">${esc(m.marketName.split(' ').slice(0,7).join(' '))}</span></div><div class="status-cluster"><span title="Market status" class="status-pill label-shape" data-status="${esc(st)}"><i></i>${st}</span><span title="Time to resolution" class="time-chip ticket-chip label-shape">${days>0?'Opening '+date(opening):'Reports opened '+date(opening)}</span>${badge(m)}${external(explorer(m)+'/address/'+m.id,'◇ '+chain(m)+' ↗','class="chain-chip label-shape" title="Chain explorer contract"')}<span title="Market type" class="type-chip label-shape">${type(m)}</span>${conditional(m)?`<a class="conditional label-shape" href="#/market/${m.parentMarket.id}" target="_blank" rel="noopener noreferrer" title="Conditional parent market">Conditional ↗</a>`:''}${external(realityUrl(m),"Answer on Reality.eth ↗",'class="reality-link"')}</div></div>`;}
// Prices are independent pool observations, never normalized or inferred.
function chartData(m){
 const series=histories.get(m.id);if(!series)return null;
 const all=[...series.values()].flat();if(!all.length)return null;
 const end=Math.max(...all.map(p=>p.t));
 const start=state.range==='All'?Math.min(...all.map(p=>p.t)):end-({'1D':86400,'1W':604800,'1M':2592000}[state.range]||0);
 const groups=outcomes(m).filter(o=>series.has(o.i)).slice(0,3).map((o,j)=>({...o,j,c:color(o,j),points:series.get(o.i).filter(p=>p.t>=start&&p.t<=end)}));
 return {start,end,groups};
}
function chanceDial(m){
 const os=outcomes(m),leader=os[0];if(!leader)return '<p class="meta">Prices unavailable</p>';
 if(scalar(m)){const up=os.find(o=>/^up$/i.test(o.name));return `<div class="scalar-ribbon"><div class="scalar-heading"><span>Market estimate</span><strong class="num">${h(estimate(m)||'Estimate unavailable')}</strong></div><div class="ribbon-track">${[0,25,50,75,100].map(v=>`<b style="left:${v}%"></b>`).join('')}${up?`<i style="left:${pct(clamp(up.p))}%" title="${h(estimate(m))}"></i>`:''}</div><div class="scalar-bounds"><span>${num(Number(m.lowerBound)/1e18)}</span><span>Estimate within range</span><span>${num(Number(m.upperBound)/1e18)}</span></div></div>`;}
 const binary=os.length===2&&os.every(o=>/^(yes|no|up|down)$/i.test(o.name));
 const pt=(t,r=116)=>[160-r*Math.cos(t*Math.PI),150-r*Math.sin(t*Math.PI)];
 const arc=(a,b)=>{const x=pt(a),y=pt(b);return `M${x[0]} ${x[1]} A116 116 0 0 1 ${y[0]} ${y[1]}`;};
 let off=0;const top=os.slice(0,3),total=top.reduce((s,o)=>s+o.p,0);
 const arcs=top.map((o,j)=>{const w=binary?(j===0?Math.min(1,o.p/100):1-off):o.p/Math.max(100,total),a=off;off+=w;return w>0?`<path class="chance-arc" data-i="${j}" data-name="${h(o.name)}" data-pct="${pct(o.p)}" tabindex="0" role="img" aria-label="${h(o.name)} ${pct(o.p)} percent" d="${arc(a,Math.min(1,off))}" stroke="${paint(o,j)}"${j===1?' stroke-dasharray="3 4"':''}/>`:'';}).join('');
 const ticks=Array.from({length:21},(_,i)=>{const [x1,y1]=pt(i/20,132),[x2,y2]=pt(i/20,i%5===0?141:136);return `<path d="M${x1} ${y1}L${x2} ${y2}"/>`;}).join('');
 return `<div class="chance-layout"><svg class="chance-dial" viewBox="0 0 320 190" role="img" aria-label="${h(leader.name)} leads at ${pct(leader.p)} percent"><g class="dial-ticks" fill="none">${ticks}</g><g fill="none" stroke-width="10"><path d="${arc(0,1)}" stroke="var(--chart-track)"/>${arcs}</g><g class="chance-needle" style="--needle-angle:${clamp(leader.p)*1.8}deg"><path d="M160 150L62 150" stroke="var(--text)" stroke-width="2"/><circle cx="160" cy="150" r="5" fill="var(--card)" stroke="var(--text)" stroke-width="2"/></g>${[0,25,50,75,100].map(v=>{const [x,y]=pt(v/100,150);return `<text x="${Math.max(12,Math.min(308,x))}" y="${y+(v===0||v===100?28:-3)}" text-anchor="middle" fill="var(--text-2)" font-size="11">${v}</text>`;}).join('')}</svg><div class="chance-headline"><strong class="num">${pct(leader.p)}<small>%</small></strong><p><b>${h(leader.name)}</b> ${binary?'chance of winning':'leads the captured pool prices'}</p><span class="gauge-caption">Market probability · 0 to 100%</span></div></div><div class="chance-labels">${top.map((o,j)=>`<span data-i="${j}" tabindex="0" class="o${j+1}" style="--outcome-color:${color(o,j)}"><i></i>${h(o.name)} <b class="num">${pct(o.p)}%</b></span>`).join('')}</div>`;
}
function payoffStrip(m){
 const os=sides(m),selected=os.find(o=>o.i===state.selected)||os[0];if(!selected)return '';
 const payout=selected.p>0?1000/selected.p:0;
 return `<section class="payoff instrument-enter" style="--step:1"><h3>If you put in 10</h3><p class="meta">Buy ${esc(selected.name)} at ${num(selected.p)} · Before fees</p><div class="payoff-bars">${[selected,...os.filter(o=>o.i!==selected.i)].slice(0,3).map((o,j)=>{const value=o.i===selected.i?payout:0;return `<div class="o${Math.min(j,2)+1}" style="--outcome-color:${color(o,j)}"><span>${scalar(m)?(/^up$/i.test(o.name)?'At upper bound':'At lower bound'):'If '+esc(o.name)+' wins'}: you get</span><strong>${num(value)}</strong><div class="payoff-track"><i style="width:${pct(value?100:0)}%"></i></div></div>`;}).join('')}</div>${scalar(m)?'<p class="meta">Scalar settlement pays proportionally within the range.</p>':''}</section>`;
}
function runway(m){
 const opened=Number(m.blockTimestamp),reports=Number(m.openingTs),end=Math.max(opened,NOW,reports),fraction=Math.max(0,Math.min(1,(NOW-opened)/Math.max(1,end-opened))),days=Math.ceil((reports-NOW)/86400);
 const events=[{label:'Opened',time:opened},{label:'Reports open',time:reports},{label:'Now',time:NOW}].sort((a,b)=>a.time-b.time);
 return `<section class="runway instrument-enter" style="--step:2"><h3>Runway <small>${days>0?days+' days until reports open':'Reports opened '+date(reports)}</small></h3><div class="runway-track" role="img" aria-label="Opened ${date(opened)}. Reports open ${date(reports)}. Snapshot now ${date(NOW)}."><i style="--progress:${pct(fraction*100)}%"></i><b class="report-tick" style="left:${pct(Math.max(0,Math.min(100,(reports-opened)/Math.max(1,end-opened)*100)))}%" title="Reports open: ${date(reports)}"></b></div><div class="runway-dates">${events.map(e=>`<span>${e.label}<b>${date(e.time)}</b></span>`).join('')}</div><p class="meta">Resolution follows reporting · Final date not fixed</p></section>`;
}
function historyVisual(m){
 const data=chartData(m);if(!data)return `<div class="history-empty">${hIcon('history')}<div><b>No recorded history</b><p>History not recorded for this market. The current snapshot is shown above.</p></div></div>`;
 const W=620,H=212,L=42,R=74,T=24,B=36,x=t=>L+(t-data.start)/Math.max(1,data.end-data.start)*(W-L-R),y=p=>H-B-p/100*(H-T-B);
 const groups=data.groups.map(g=>{const pts=g.points;const line=pts.map((p,i)=>`${i?'L':'M'}${x(p.t)} ${y(p.p)}`).join(' ');return `<g data-series="${g.j}">${pts.length>1?`<path d="${line}L${x(pts.at(-1).t)} ${H-B}L${x(pts[0].t)} ${H-B}Z" fill="${g.c}" opacity=".07"/><path d="${line}" class="history-line" fill="none" stroke="${g.c}" stroke-width="2"${g.j===1?' stroke-dasharray="5 4"':''}/>`:''}${pts.map((p,i)=>`<circle cx="${x(p.t)}" cy="${y(p.p)}" r="${i===pts.length-1?3.5:1.8}" fill="${g.c}"><title>${h(g.name)} ${pct(p.p)}% · ${date(p.t)}</title></circle>`).join('')}${pts.length?`<text x="${W-R+10}" y="${Math.max(T+12,Math.min(H-B-6,y(pts.at(-1).p)-8))}" fill="${g.c}" font-size="11">${h(compactName(g.name))} ${pct(pts.at(-1).p)}%</text>`:''}</g>`;}).join('');
 return `<section class="history-panel"><div class="chart-head"><h3>How the odds moved</h3><div class="ranges">${['1D','1W','1M','All'].map(r=>`<button data-range="${r}" aria-pressed="${state.range===r}" class="${state.range===r?'active':''}">${r}</button>`).join('')}</div></div><div class="history-canvas" tabindex="0" role="img" aria-label="Recorded odds. Use left and right arrows to read observations."><svg class="history-ridge" viewBox="0 0 ${W} ${H}" aria-label="Recorded odds, zero to one hundred percent">${[0,25,50,75,100].map(p=>`<path d="M${L} ${y(p)}H${W-R}" stroke="var(--line)"/><text x="${L-9}" y="${y(p)+4}" text-anchor="end" fill="var(--text-2)" font-size="11">${p}%</text>`).join('')}${groups}<g class="history-crosshair" hidden><path class="crosshair-line" y1="${T}"/><circle r="4"/><rect width="192" height="40" rx="6"/><text></text></g><text x="${L}" y="${H-8}" fill="var(--text-2)" font-size="11">${date(data.start)}</text><text x="${W-R}" y="${H-8}" text-anchor="end" fill="var(--text-2)" font-size="11">${date(data.end)}</text></svg></div><div class="history-labels">${data.groups.map(g=>`<span style="--outcome-color:${g.c}"><i></i>${h(g.name)} <b>${g.points.length?pct(g.points.at(-1).p)+'%':'No observations in window'}</b></span>`).join('')}</div><p class="meta">Captured pool observations · Actual timestamps · No interpolation</p></section>`;
}
function winningChart(m){return `<div class="instrument-enter">${chanceDial(m)}</div><div id="payoff-strip">${payoffStrip(m)}</div>${runway(m)}<div id="history-panel" class="instrument-enter" style="--step:3">${historyVisual(m)}</div>`;}
function animateInstrument(root){if(!root||reduced())return;for(const el of root.querySelectorAll('.chance-needle'))el.animate([{transform:'rotate(0deg)'},{transform:`rotate(${el.style.getPropertyValue('--needle-angle')})`}],{duration:600,easing:'cubic-bezier(.16,1,.3,1)'});}
function wireChart(m){wireHistory(m);animateInstrument($('#winning-chart'));}
function wireHistory(m){document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{state.range=b.dataset.range;$('#history-panel').innerHTML=historyVisual(m);wireHistory(m);});hHistoryCrosshair(m);hSegment($('#history-panel'));}
/* Balance scale: beam angle springs toward a target set by position size (amount / SCALE_MAX) and the pay vs get ratio.
   The heavier Get pan sits on the side of the chosen outcome button, so switching Yes/No flips the tilt. */
const sc={x:0,v:0,t:0,raf:0,getLeft:true,oc:0,nL:0,nR:0};
const BEAM=112;
function scaleSvg(getLeft,oc){const pan=(id,get)=>`<g id="${id}" class="sc-pan${get?' get':''}"><path class="sc-str" d="M0 0 -30 57M0 0 30 57"/><circle class="sc-hook" r="2"/><g class="sc-coins" id="${id}-c"></g><path class="sc-dish" d="M-36 57h72c-4 11-17 17-36 17S-32 68-36 57Z"/><path class="pan-rim" d="M-36 57h72"/></g>`;return `<div class="sc-wrap o${oc+1}"><svg class="sc" viewBox="0 0 320 156" role="img" aria-label="Balance scale: what you pay against what you get"><ellipse class="sc-shadow" cx="160" cy="145" rx="88" ry="3"/><path class="sc-post" d="M157 41h6l5 94h-16Z"/><path class="post-edge" d="M160 47v82"/><rect class="sc-foot" x="128" y="135" width="64" height="6" rx="3"/>${pan('sc-l',getLeft)}${pan('sc-r',!getLeft)}<g id="sc-beam"><path class="sc-beam" d="M${160-BEAM} 34H${160+BEAM}"/><path class="beam-edge" d="M${160-BEAM} 32H${160+BEAM}"/><circle class="sc-end" cx="${160-BEAM}" cy="34" r="3"/><circle class="sc-end" cx="${160+BEAM}" cy="34" r="3"/></g><circle class="sc-pivot" cx="160" cy="34" r="7"/><circle class="sc-pin" cx="160" cy="34" r="2.5"/></svg></div>`;}
function coins(n,prev,get){return Array.from({length:n},(_,i)=>{const y=52-i*4.5;return `<g class="cn${i>=prev?' cn-new':''}"><ellipse cx="0" cy="${y+3}" rx="18" ry="4" class="cn-side"/><path d="M-18 ${y}v3a18 4 0 0 0 36 0v-3" class="cn-side"/><ellipse cx="0" cy="${y}" rx="18" ry="4" class="cn-top${get?' cn-get':''}"/><path d="M-13 ${y}a13 2 0 0 0 26 0" class="coin-etch"/></g>`;}).join('');}
function placeScale(){const bm=$('#sc-beam');if(!bm)return;const a=sc.x*Math.PI/180,cx=BEAM*Math.cos(a),cy=BEAM*Math.sin(a);bm.setAttribute('transform',`rotate(${sc.x.toFixed(3)} 160 34)`);$('#sc-l').setAttribute('transform',`translate(${(160-cx).toFixed(2)} ${(34-cy).toFixed(2)})`);$('#sc-r').setAttribute('transform',`translate(${(160+cx).toFixed(2)} ${(34+cy).toFixed(2)})`);}
function scaleTo(pay,get){const size=Math.min(1,pay/SCALE_MAX),ratio=pay>0?(get-pay)/(get+pay):0,mag=pay>0?Math.min(16,(.15+.85*Math.sqrt(size))*(5+11*Math.max(0,ratio))):0;
 const n=v=>v>0?Math.max(1,Math.min(10,1+Math.round(v/SCALE_MAX*8))):0,nPay=n(pay),nGet=n(get);
 const L=sc.getLeft?nGet:nPay,R=sc.getLeft?nPay:nGet,lc=$('#sc-l-c'),rc=$('#sc-r-c');
 if(lc&&rc){const fresh=!lc.childElementCount&&!rc.childElementCount;lc.innerHTML=coins(L,fresh?L:sc.nL,sc.getLeft);rc.innerHTML=coins(R,fresh?R:sc.nR,!sc.getLeft);sc.nL=L;sc.nR=R;}
 sc.t=(sc.getLeft?-1:1)*mag;
 if(reduced()){cancelAnimationFrame(sc.raf);sc.raf=0;sc.x=sc.t;sc.v=0;placeScale();return;}
 if(sc.raf)return;let last=performance.now();
 const step=now=>{const dt=Math.min(.032,(now-last)/1000);last=now;const acc=-260*(sc.x-sc.t)-20*sc.v;sc.v+=acc*dt;sc.x+=sc.v*dt;
  if(Math.abs(sc.v)<.02&&Math.abs(sc.x-sc.t)<.02){sc.x=sc.t;sc.v=0;sc.raf=0;placeScale();return;}placeScale();sc.raf=requestAnimationFrame(step);};
 sc.raf=requestAnimationFrame(step);}
/* Rolling digits: one reel per digit, reel window = line box = item height (--rd-h). Only changed digits move; the least
   significant digit crossfades; at most two digits roll per tick; reduced motion snaps. */
function reel(ch){return /\d/.test(ch)?`<span class="rd" aria-hidden="true"><span class="rd-col" style="--d:${ch}">${'0123456789'.split('').map(d=>`<span>${d}</span>`).join('')}</span></span>`:`<span class="rs" aria-hidden="true">${ch}</span>`;}
function rollTo(el,text){if(!el)return;const prev=el.dataset.v;el.dataset.v=text;el.setAttribute('aria-label',text);el.setAttribute('role','img');
 if(prev==null||reduced()||prev.length!==text.length||el.children.length!==text.length){el.innerHTML=[...text].map(reel).join('');return;}
 const last=text.search(/\d(?=\D*$)/);let rolled=0;
 [...text].forEach((ch,i)=>{if(ch===prev[i])return;const c=el.children[i];if(!/\d/.test(ch)||!c.classList.contains('rd')){c.outerHTML=reel(ch);return;}const col=c.firstChild;
  if(i===last||rolled>=2){col.classList.add('snap');col.style.setProperty('--d',ch);void col.offsetWidth;col.classList.remove('snap');c.classList.remove('xf');void c.offsetWidth;c.classList.add('xf');}
  else{rolled++;col.style.setProperty('--d',ch);}});}

/* In-app trade flow, shared by the list panel and the full market page: wallet state, validation, confirm sheet, success */
const wallet={addr:(()=>{try{return sessionStorage.getItem('seer.wallet')||'';}catch{return '';}})(),balance:2500};
const MIN_AMT=1,MAX_AMT=10000,SLIP=0.5,FEE=0.002;
function connected(){const s=window.seerShell;if(s&&typeof s.isConnected==='function')return !!s.isConnected();if(s&&typeof s.address==='string')return !!s.address;return !!wallet.addr;}
function connect(){const s=window.seerShell;if(s&&typeof s.openConnect==='function'){s.openConnect();return;}window.dispatchEvent(new CustomEvent('seer:connect',{cancelable:true}));setTimeout(()=>{if(document.querySelector('.sg-modal-wrap'))return;[...document.querySelectorAll('body > header button, .sg button')].find(b=>/connect/i.test(b.textContent))?.click();},60);}
function walletChanged(){if(isHome())panel();else if(route().startsWith('#/market/'))setCta();}
window.addEventListener('seer:wallet',e=>{wallet.addr=e.detail?.address||'connected';walletChanged();});
window.addEventListener('seer:disconnect',()=>{wallet.addr='';walletChanged();});
function amountError(a){if(!(a>0))return 'Enter an amount to pay';if(a<MIN_AMT)return `Minimum order is ${MIN_AMT}`;if(a>MAX_AMT)return `Maximum order is ${num(MAX_AMT)}`;if(a>wallet.balance)return `Exceeds demo balance of ${num(wallet.balance)}`;return '';}
function setCta(){const b=$('#tr-go');if(!b)return;const q=state.q,on=connected(),err=q?amountError(q.pay):'';b.textContent=`Preview buy ${q?.name||''}`;b.classList.toggle('o2',on&&sc.oc===1);const e=$('#tr-err');if(e)e.textContent=err;$('#amount')?.setAttribute('aria-invalid',String(!!err));const bal=$('#amt-bal');if(bal)bal.textContent=`Demo balance ${num(wallet.balance)}`;}
function txHash(){const b=new Uint8Array(32);crypto.getRandomValues(b);return '0x'+[...b].map(x=>x.toString(16).padStart(2,'0')).join('');}
function confirmTrade(q){const rows=q.sell?[['You sell',num(q.pay)+' shares'],['You receive, about',num(q.get)],['Avg price',num(q.avg*100)]]:[['You pay',num(q.pay)],[scalar(q.m)?`Get at ${/^up$/i.test(q.name)?'upper':'lower'} bound`:`You get if ${q.name} wins`,num(q.get)+' shares'],['Avg price',num(q.avg*100)]];rows.push(['Max slippage',SLIP+'%'],['Fees, est.',num(q.pay*FEE)]);
 modal(`Simulate: ${q.sell?'Sell':'Buy'} ${q.name}`,`<p class="demo-notice">Local preview only. No order is submitted and no funds move.</p><p class="cf-q">${esc(q.m.marketName)}</p><dl class="cf-dl">${rows.map(([a,b])=>`<div><dt>${esc(a)}</dt><dd class="num">${b}</dd></div>`).join('')}</dl><div class="cf-act"><button class="soft" id="cf-cancel">Cancel</button><button class="primary" id="cf-ok">Simulate order</button></div>`);
 dialog.classList.add('cf');$('#cf-cancel').onclick=()=>dialog.close();
 $('#cf-ok').onclick=()=>{const b=$('#cf-ok');b.disabled=true;b.textContent='Simulating';setTimeout(()=>tradeDone(q),reduced()?0:700);};$('#cf-ok').focus();}
function tradeDone(q){if(!dialog.open)return;dialog.setAttribute('aria-label','Simulation complete');const hash=txHash();wallet.balance=Math.max(0,wallet.balance+(q.sell?q.get:-q.pay));
 dialog.innerHTML=`<button class="close" aria-label="Close dialog">×</button><span class="cf-mark" aria-hidden="true"><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12 5 5 9-10"/></svg></span><h2>Simulation complete</h2><p class="demo-notice">Demo values only. No transaction was sent.</p><p class="cf-q">${q.sell?`Simulated selling ${num(q.pay)} ${esc(q.name)} shares for about ${num(q.get)}.`:`Demo position: ${num(q.get)} ${esc(q.name)} shares. ${scalar(q.m)?`They pay up to ${num(q.get)} at the ${/^up$/i.test(q.name)?'upper':'lower'} bound and settle proportionally within the range.`:`They pay ${num(q.get)} if ${esc(q.name)} wins.`}`}</p><dl class="cf-dl"><div><dt>Simulation ID</dt><dd class="mono" title="${hash}">${short(hash)}</dd></div><div><dt>Demo position</dt><dd class="num">${num(q.sell?0:q.get)} ${esc(q.name)}</dd></div><div><dt>Demo balance</dt><dd class="num">${num(wallet.balance)}</dd></div></dl><div class="cf-act"><button class="soft" id="cf-done">Done</button><a class="primary" id="cf-view" href="#/market/${q.m.id}">View market</a></div>`;
 $('.close',dialog).onclick=()=>dialog.close();$('#cf-done').onclick=()=>dialog.close();$('#cf-view').onclick=()=>dialog.close();$('#cf-view').focus();walletChanged();}
dialog.addEventListener('close',()=>dialog.classList.remove('cf'));

const leaders={data:null,period:'All',app:'All',chain:'All',search:'',sort:'pnl',desc:true,page:0};
async function leaderboard(){closeMenu(false);if(!leaders.data){app.innerHTML='<div class="loading">Loading leaderboard…</div>';try{const r=await fetch('./data/get-pnl-leaderboard.json');if(!r.ok)throw Error('leaderboard');leaders.data=(await r.json()).data;}catch{app.innerHTML='<div class="empty">Could not load leaderboard. <button id="retry-leaders">Retry</button></div>';$('#retry-leaders').onclick=leaderboard;return;}if(location.hash!=='#/leaderboard')return;}
const d=leaders.data;const top=[...d.rows].sort((a,b)=>b.pnl-a.pnl)[0];
app.innerHTML=`<section class="leaderboard"><div class="leader-heading"><div><a href="#/" class="meta">Markets /</a><h1>Leaderboard</h1><p class="meta">Trader performance · ${new Date(d.updatedAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</p></div><button class="soft" id="your-rank">Your rank</button></div><div class="leader-controls"><div class="period-tabs" aria-label="Leaderboard period">${['1D','1W','1M','All'].map(p=>p==='All'?`<button data-period="All" aria-pressed="true">All time</button>`:`<span class="lp-wrap"><button aria-disabled="true" data-period-na="${p}" aria-describedby="lp-why" aria-pressed="false">${p}</button></span>`).join('')}<span class="lp-tip" id="lp-why" role="tooltip">Seer's leaderboard feed returns all-time totals only, with no per-trade timestamps, so 1D, 1W and 1M rankings cannot be derived.</span></div><button class="sentence-trigger" data-leader-filter="app" aria-expanded="false">App: ${esc(leaders.app)} ⌄</button><button class="sentence-trigger" data-leader-filter="chain" aria-expanded="false">Chain: ${esc(leaders.chain)} ⌄</button></div><p class="meta" role="status" id="leader-status"></p>${leaderVisuals(d.rows)}<div class="leader-search-row"><input type="search" id="leader-search" placeholder="Search address or username" aria-label="Search address or username" value="${esc(leaders.search)}"></div><div id="leader-table-area"></div><details class="score-explainer"><summary>How the Trader Score works</summary><p>Scores combine returns, profit factor, hit rate, loss burn and market breadth. Small samples are reduced toward the baseline. At least three scored markets are required.</p><div class="score-components">${Object.entries(top.scoreBreakdown.components).map(([k,v])=>`<span>${esc(k)} <b>${num(v)}</b></span>`).join('')}</div><small>Component values for rank 1 · Score ${top.score}</small></details><footer class="footer"><span>Snapshot · 25 captured accounts of 4,130</span><a href="https://app.seer.pm/leaderboard" target="_blank" rel="noopener noreferrer">Full live leaderboard ↗</a></footer></section>`;
leaderTable();
document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{leaders.period=b.dataset.period;leaders.page=0;leaderboard();});document.querySelectorAll('[data-period-na]').forEach(b=>b.onclick=()=>toast(`${b.dataset.periodNa} ranking unavailable: the feed has all-time totals only`));document.querySelectorAll('[data-leader-filter]').forEach(b=>hoverMenu(b,()=>{const key=b.dataset.leaderFilter;const options=key==='app'?['All','Seer','Futarchy','Deepfunding','Foresight']:['All','Gnosis','Ethereum','OP Mainnet','Base'];menu(b,`<div class="menu-title">${key==='app'?'Application':'Chain'}</div>${options.map(v=>`<button data-leader-option="${v}" aria-pressed="${leaders[key]===v}">${v}<span>${leaders[key]===v?'✓':''}</span></button>`).join('')}`);pop.querySelectorAll('[data-leader-option]').forEach(o=>o.onclick=()=>{leaders[key]=o.dataset.leaderOption;leaders.page=0;closeMenu();leaderboard();document.querySelector('[data-leader-filter='+key+']')?.focus();});}));$('#leader-search').oninput=e=>{leaders.search=e.target.value;leaders.page=0;leaderTable();};$('#your-rank').onclick=()=>{modal('Your rank','<p>Search the captured leaderboard by wallet address.</p><form id="rank-form"><label for="rank-address">Wallet address</label><input id="rank-address" required placeholder="0x…" style="width:100%;margin:16px 0"><button class="primary">Find rank</button></form>');$('#rank-form').onsubmit=e=>{e.preventDefault();leaders.search=$('#rank-address').value.trim();leaders.period=leaders.app=leaders.chain='All';leaders.page=0;dialog.close();leaderboard();};};}

function leaderTable(){const d=leaders.data,available=leaders.period==='All'&&leaders.app==='All'&&leaders.chain==='All';let rows=available?d.rows.filter(r=>((r.username||'')+' '+r.address).toLowerCase().includes(leaders.search.trim().toLowerCase())):[];rows.sort((a,b)=>((a[leaders.sort]??-Infinity)-(b[leaders.sort]??-Infinity))*(leaders.desc?-1:1));const pages=Math.max(1,Math.ceil(rows.length/10));leaders.page=Math.min(leaders.page,pages-1);
$('#leader-status').textContent=available?`${rows.length} captured accounts of ${num(d.total)} total · All-time · All apps · All chains`:`${leaders.period} · ${leaders.app} apps · ${leaders.chain} chains: this snapshot was not captured.`;
$('#leader-table-area').innerHTML=`<div class="leader-table-wrap"><table class="leader-table"><thead><tr>${[['rank','Rank'],['address','Account'],['score','Trader Score'],['pnl','Profit / loss'],['volume','Volume'],['roi','ROI'],['marketCount','Markets']].map(([k,label])=>`<th scope="col" ${leaders.sort===k?`aria-sort="${leaders.desc?'descending':'ascending'}"`:''}>${k==='address'?label:`<button data-leader-sort="${k}">${label}${leaders.sort===k?(leaders.desc?' ↓':' ↑'):''}</button>`}</th>`).join('')}</tr></thead><tbody>${rows.slice(leaders.page*10,leaders.page*10+10).map((r,i)=>`<tr style="--row:${i}"><td>${r.rank}</td><td><a class="account-cell" href="https://gnosisscan.io/address/${r.address}" target="_blank" rel="noopener noreferrer"><span class="avatar-glyph" aria-hidden="true">${r.address.slice(2,4).toUpperCase()}</span><span class="mono">${esc(r.username||short(r.address))} ↗</span></a></td><td><button class="score-badge" data-score="${r.address}" aria-label="Trader score details for ${short(r.address)}"><svg viewBox="0 0 32 32"><circle cx="16" cy="16" r="12" fill="none" stroke="var(--nested)" stroke-width="3"/><circle cx="16" cy="16" r="12" fill="none" stroke="var(--violet-text)" stroke-width="3" pathLength="100" stroke-dasharray="${r.score||0} 100" transform="rotate(-90 16 16)"/></svg><span>${r.score==null?'Unscored':num(r.score)}<small class="tier-chip label-shape" title="Trader score tier">${esc(r.tier||'1 scored market')}</small></span></button></td><td class="${r.pnl<0?'negative':'positive'}">${r.pnl<0?'−':'+'}${money(Math.abs(r.pnl))}</td><td>${money(r.volume)}</td><td class="${r.roi<0?'negative':'positive'}">${r.roi<0?'−':'+'}${pct(Math.abs(r.roi)*100)}%</td><td>${r.marketCount}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">'+(available?'No matching accounts':'No captured rows for these filters')+'</td></tr>'}</tbody></table></div><div class="leader-pagination"><button id="leader-prev" class="soft" ${leaders.page===0?'disabled title="First page"':''}>Previous</button><span>Page ${leaders.page+1} of ${pages}</span><button id="leader-next" class="soft" ${leaders.page===pages-1?'disabled title="Last captured page"':''}>Next</button></div>`;
document.querySelectorAll('[data-leader-sort]').forEach(b=>b.onclick=()=>{const k=b.dataset.leaderSort;leaders.desc=leaders.sort===k?!leaders.desc:true;leaders.sort=k;leaders.page=0;leaderTable();});$('#leader-prev').onclick=()=>{leaders.page--;leaderTable();};$('#leader-next').onclick=()=>{leaders.page++;leaderTable();};
document.querySelectorAll('[data-score]').forEach(b=>b.onclick=()=>{const r=d.rows.find(r=>r.address===b.dataset.score);modal('Trader Score',r.scoreBreakdown?`<p>${num(r.score)} · ${esc(r.tier)}</p><div class="detail-list">${Object.entries(r.scoreBreakdown.components).map(([k,v])=>`<div><span>${esc(k)}</span><b>${num(v)}</b></div>`).join('')}</div><p>${r.scoreBreakdown.sampleShrink.scoredMarketCount} scored markets · Sample factor ${pct(r.scoreBreakdown.sampleShrink.factor*100)}%</p>`:`<p>${r.scoreUnavailable.scoredMarketCount} scored market. At least ${r.scoreUnavailable.minScoredMarkets} are required.</p>`);});}


