(function(){const tip=document.createElement('div');tip.className='chance-tip';tip.setAttribute('role','tooltip');tip.hidden=true;document.body.append(tip);
const set=(i,on)=>{document.querySelectorAll('.chance-dial').forEach(d=>{d.classList.toggle('has-focus',on);d.querySelectorAll('.chance-arc').forEach(a=>a.classList.toggle('is-on',on&&a.dataset.i===String(i)));});document.querySelectorAll('.chance-labels [data-i]').forEach(l=>l.classList.toggle('is-on',on&&l.dataset.i===String(i)));};
const show=(a,x,y)=>{tip.innerHTML='<b>'+a.dataset.name+'</b><span>'+pct(a.dataset.pct)+'% chance</span>';tip.hidden=false;const w=tip.offsetWidth,h=tip.offsetHeight;tip.style.left=Math.max(8,Math.min(innerWidth-w-8,x+14))+'px';tip.style.top=Math.max(8,y-h-12)+'px';};
document.addEventListener('pointermove',e=>{const a=e.target.closest?.('.chance-arc');if(a){set(a.dataset.i,true);show(a,e.clientX,e.clientY);return;}const l=e.target.closest?.('.chance-labels [data-i]');if(l){const arc=document.querySelector('.chance-arc[data-i="'+l.dataset.i+'"]');set(l.dataset.i,true);if(arc){const r=arc.getBoundingClientRect();show(arc,r.left+r.width/2,r.top+r.height/2);}return;}if(!tip.hidden){tip.hidden=true;set(0,false);}});
document.addEventListener('focusin',e=>{const t=e.target.closest?.('.chance-arc,.chance-labels [data-i]');if(!t)return;const i=t.dataset.i;const arc=document.querySelector('.chance-arc[data-i="'+i+'"]');set(i,true);if(arc){const r=arc.getBoundingClientRect();show(arc,r.left+r.width/2,r.top+r.height/2);}});
document.addEventListener('focusout',e=>{if(e.target.closest?.('.chance-arc,.chance-labels [data-i]')){tip.hidden=true;set(0,false);}});
addEventListener('hashchange',()=>{tip.hidden=true;});})();

// The source appendix calls this helper but omits its declaration. Geometry follows
// the brief's coin chart measurements; stack height comes only from captured PnL.
function coin(x,y,rx,ry,depth,i,c){return `<g class="coin" style="--i:${i};color:${c}"><ellipse cx="${x}" cy="${y+depth}" rx="${rx}" ry="${ry}" class="coin-side"/><path d="M${x-rx} ${y}v${depth}a${rx} ${ry} 0 0 0 ${rx*2} 0v-${depth}" class="coin-side"/><ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" class="coin-face"/><ellipse cx="${x}" cy="${y}" rx="${rx-4}" ry="${ry-2}" class="coin-etch"/></g>`;}
function leaderVisuals(rows){const top=[...rows].sort((a,b)=>b.pnl-a.pnl).slice(0,10),max=Math.max(1,...top.map(r=>Math.max(0,r.pnl)));return `<section class="top-coins" aria-label="Top 10 traders by profit"><div class="top-coins-row">${top.map((r,k)=>{const c=k===0?'var(--o1)':k<3?'var(--o2)':'var(--o3)';const n=Math.max(1,Math.round(Math.max(0,r.pnl)/max*22));return `<div class="top-coin" title="Rank ${k+1}: ${money(r.pnl)}"><svg viewBox="0 0 64 150" role="img" aria-label="Rank ${k+1}, ${money(r.pnl)} profit"><ellipse class="coin-shadow" cx="32" cy="142" rx="27" ry="6"/>${Array.from({length:n},(_,i)=>coin(32,134-i*6,24,6.5,5,i,c)).join('')}</svg><b>#${k+1}</b><span class="mono">${short(r.address)}</span><em>${r.pnl<0?'−':'+'}${money(Math.abs(r.pnl))}</em></div>`;}).join('')}</div></section>`;}



function normalizeLegacyRoute(){
 const hash=location.hash;
 if(hash.startsWith('#/markets')){const old=new URLSearchParams(hash.split('?')[1]||'');const q=new URLSearchParams();for(const [k,v]of old){const key={marketName:'q',kind:'type',view:'view'}[k]||k;if(key==='view'&&v==='index')q.set(key,'table');else if(key==='type'&&v==='Multi-categorical')q.set(key,'Categorical');else if(key==='type'&&v==='Multi-scalar')q.set(key,'Multi-outcome');else q.set(key,v);}history.replaceState(null,'','#/?'+q);}
 const value=decodeURIComponent((location.hash.match(/^#\/market\/(.+?)(?:\?|$)/)||[])[1]||'');
 if(value&&!state.markets.some(m=>m.id===value)){const slug=value.split('/').pop(),m=state.markets.find(m=>m.url===slug||m.id===slug);if(m)history.replaceState(null,'','#/market/'+m.id);}
}

// Shared captured-data preparation, exercised by command-deck.mjs.
function prepareMarkets(data){const byId=new Map();data.markets.forEach(m=>{if(!byId.has(m.id))byId.set(m.id,m);});state.markets=[...byId.values()];const names=new Map();[...state.markets].sort((a,b)=>Number(!!conditional(a))-Number(!!conditional(b))).forEach(m=>{const key=m.marketName.trim().toLowerCase().replace(/\s+/g,' ');if(!names.has(key))names.set(key,m);});state.listMarkets=[...names.values()].filter(m=>Number(m.volumeUSD)>0&&outcomes(m).length>0&&m.outcomes.every((n,i)=>n.trim().toLowerCase()==='invalid'||Number.isFinite(m.odds?.[i])));}

// Keep keyboard focus within the mobile overlays; native dialogs manage their own focus.
document.addEventListener('keydown',e=>{
 if(dialog.open||e.key!=='Tab')return;
 const panel=!desktop()?document.querySelector('#ix-panel.open'):null;
 const consolePanel=innerWidth<=1050?document.querySelector('.trade.open'):null;
 const overlay=panel||consolePanel;if(!overlay)return;
 const items=[...overlay.querySelectorAll('a[href],button,input,select,summary,[tabindex="0"]')].filter(el=>!el.disabled&&!el.closest('[inert]')&&el.getClientRects().length);
 if(!items.length)return;const i=items.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&(i===items.length-1||i<0)){e.preventDefault();items[0].focus();}
});

function toggleConsole(open){const el=$('.trade');if(!el)return;el.classList.toggle('open',open);$('#mobile-trade')?.setAttribute('aria-expanded',String(open));if(innerWidth<=1050){if(open){el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');}else{el.removeAttribute('role');el.removeAttribute('aria-modal');}document.body.classList.toggle('console-open',open);(open?$('.trade-close'):$('#mobile-trade'))?.focus({preventScroll:true});}}

function hIcon(name){return `<svg class="ui-icon" viewBox="0 0 20 20" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="#h-${name}"/></svg>`;}

function hMark(m){
 const os=outcomes(m),l=os[0];if(!l)return '';
 if(baseKind(m)==='Scalar'){const up=os.find(o=>/^up$/i.test(o.name)),v=up?.p||0;return `<div class="tile-mark scalar-mark" aria-label="Estimate ${h(estimate(m))}"><strong class="num">${h(estimate(m).replace(/\s+\S+$/,''))}<small>${h(unitOf(m))}</small></strong>${unitOf(m)?'':'<span>estimate</span>'}<svg viewBox="0 0 72 18" aria-hidden="true"><path d="M2 8H70" class="mark-track"/>${[2,19,36,53,70].map(x=>`<path d="M${x} 5v6" class="mark-tick"/>`).join('')}<path d="M${2+.68*v} 2v12" stroke="var(--o1)" stroke-width="3"/></svg></div>`;}
 const pt=t=>[36-30*Math.cos(t*Math.PI),32-30*Math.sin(t*Math.PI)],a=(x,y)=>{const p=pt(x),q=pt(y);return `M${p[0]} ${p[1]}A30 30 0 0 1 ${q[0]} ${q[1]}`;};let off=0;const denom=Math.max(100,os.reduce((s,o)=>s+o.p,0));
 return `<div class="tile-mark" role="img" aria-label="${h(l.name)} leads at ${pct(l.p)} percent"><strong class="num">${pct(l.p)}<small>%</small></strong><svg viewBox="0 0 72 38" aria-hidden="true"><path d="${a(0,1)}" class="mark-track"/>${os.slice(0,3).map((o,j)=>{const start=off;off=Math.min(1,off+o.p/denom);return `<path d="${a(start,off)}" stroke="${color(o,j)}" class="mark-segment"${j===1?' stroke-dasharray="2 3"':''}/>`;}).join('')}<path d="M36 0v6" class="mark-tick"/></svg></div>`;
}

function hQuickError(a,buy=true){if(!Number.isFinite(a)||a<=0)return 'Enter an amount greater than zero.';if(a<1)return 'Minimum amount is 1.';if(a>10000)return 'Maximum amount is 10,000.';if(buy&&a>wallet.balance)return `Exceeds demo balance of ${num(wallet.balance)}.`;return '';}

function hWireQuickAmount(m){const input=$('#quick-amount');if(!input)return;input.addEventListener('input',()=>{const value=input.value,focused=document.activeElement===input,scroll=$('.pn-scroll')?.scrollTop||0;state.tAmt=Number(value)||0;panel();const next=$('#quick-amount');next.value=value;$('.pn-scroll').scrollTop=scroll;if(focused)next.focus({preventScroll:true});});}

function hSyncPanels(){
 cancelAnimationFrame(window.hPanelFrame||0);window.hPanelFrame=requestAnimationFrame(()=>{
  for(const panel of document.querySelectorAll('#ix-panel,.trade')){
   const r=panel.getBoundingClientRect(),offset=innerWidth>=1100?Math.max(128,r.top):innerWidth>1050&&panel.matches('.trade')?Math.max(128,r.top):80;
   panel.style.setProperty('--panel-offset',offset+'px');
   const scroller=panel.querySelector('.pn-scroll,.trade-body');if(!scroller)continue;
   const update=()=>{panel.classList.toggle('can-scroll-up',scroller.scrollTop>2);panel.classList.toggle('can-scroll-down',scroller.scrollTop+scroller.clientHeight<scroller.scrollHeight-2);};
   scroller.onscroll=update;update();
  }
 });
}

function hSyntax(root=document){for(const pre of root.querySelectorAll('pre')){const text=pre.textContent;if(!/^[\s\n]*[\{\[]/.test(text))continue;pre.innerHTML=h(text).replace(/(&quot;[^\n]*?&quot;)(\s*:)?|\b(true|false|null)\b|\b(-?\d+(?:\.\d+)?)\b/g,(match,str,key,word,n)=>str?`<span class="json-${key?'key':'string'}">${str}</span>${key||''}`:`<span class="json-${word?'literal':'number'}">${word||n}</span>`);}}

function hSegment(root=document){for(const el of root.querySelectorAll('.seg,.mode,.period-tabs,.pn-ranges,.ranges,.tabs')){const items=[...el.querySelectorAll(':scope > button')],active=items.find(x=>x.getAttribute('aria-pressed')==='true'||x.classList.contains('active'));if(!active)continue;const r=active.getBoundingClientRect(),p=el.getBoundingClientRect();el.style.setProperty('--thumb-x',(r.left-p.left)+'px');el.style.setProperty('--thumb-w',r.width+'px');}}

function hHistoryCrosshair(m){
 const host=$('.history-canvas'),data=chartData(m);if(!host||!data)return;const points=data.groups[0]?.points||[];if(!points.length)return;let index=points.length-1;
 const draw=i=>{index=Math.max(0,Math.min(points.length-1,i));const p=points[index],x=42+(p.t-data.start)/Math.max(1,data.end-data.start)*504,y=176-p.p*1.52,g=$('.history-crosshair',host);if(!g)return;g.hidden=false;g.removeAttribute('hidden');const line=$('path',g);line.setAttribute('d',`M${x} 24V176`);$('circle',g).setAttribute('cx',x);$('circle',g).setAttribute('cy',y);const left=Math.max(44,Math.min(350,x-96));$('rect',g).setAttribute('x',left);$('rect',g).setAttribute('y','24');const label=$('text',g);label.setAttribute('x',left+10);label.setAttribute('y','48');label.textContent=`${pct(p.p)}% · ${date(p.t)}`;host.setAttribute('aria-label',`${data.groups[0].name}, ${pct(p.p)} percent on ${date(p.t)}. Use arrows to read observations.`);};
 host.onpointermove=e=>{const r=host.getBoundingClientRect(),t=data.start+Math.max(0,Math.min(1,((e.clientX-r.left)/r.width*620-42)/504))*(data.end-data.start);let best=0;points.forEach((p,i)=>{if(Math.abs(p.t-t)<Math.abs(points[best].t-t))best=i;});draw(best);};
 host.onpointerleave=()=>$('.history-crosshair',host)?.setAttribute('hidden','');host.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();draw(e.key==='Home'?0:e.key==='End'?points.length-1:index+(e.key==='ArrowRight'?1:-1));}};
}

document.addEventListener('click',e=>{const b=e.target.closest('[data-open-trade]');if(b){e.stopPropagation();location.hash='#/market/'+b.dataset.openTrade;return;}const c=e.target.closest('[data-copy-asker],[data-copy-value]');if(c){e.stopPropagation();copy(c.dataset.copyAsker||c.dataset.copyValue);}},true);
